1: import { FastifyRequest, FastifyReply } from 'fastify';
2: import crypto from 'crypto';
3: import jwt from 'jsonwebtoken';
4: import { config } from '../config/index.js';
5: import { prisma } from '../config/database.js';
6: import type { User, UserRole } from '../types/index.js';
7: 
8: // ---------------------------------------------------------------------------
9: // Cognito verifier — only initialized when AUTH_MODE=cognito
10: // ---------------------------------------------------------------------------
11: let cognitoVerifier: any = null;
12: 
13: async function getCognitoVerifier() {
14:   if (cognitoVerifier) return cognitoVerifier;
15:   if (config.authMode !== 'cognito') return null;
16:   const { CognitoJwtVerifier } = await import('aws-jwt-verify');
17:   cognitoVerifier = CognitoJwtVerifier.create({
18:     userPoolId: config.cognito.userPoolId,
19:     tokenUse: 'id' as const,
20:     clientId: config.cognito.clientId,
21:   });
22:   return cognitoVerifier;
23: }
24: 
25: /**
26:  * Verifies a Cognito id_token and returns normalized claims.
27:  */
28: export async function verifyToken(token: string) {
29:   if (config.authMode === 'local') {
30:     return verifyLocalToken(token);
31:   }
32:   const verifier = await getCognitoVerifier();
33:   const payload = await verifier.verify(token);
34:   return {
35:     sub: payload.sub,
36:     email: (payload.email ?? payload['cognito:username']) as string,
37:     orgId: payload['custom:orgId'] as string | undefined,
38:     role: (payload['custom:role'] as UserRole) || 'owner',
39:   };
40: }
41: 
42: // ---------------------------------------------------------------------------
43: // Local JWT auth (for non-Cognito mode)
44: // ---------------------------------------------------------------------------
45: 
46: /**
47:  * Creates a local JWT for username/password auth.
48:  */
49: export function createLocalJwt(claims: {
50:   sub: string;
51:   email: string;
52:   orgId: string;
53:   role: UserRole;
54: }): string {
55:   return jwt.sign(claims, config.jwtSecret, { expiresIn: '24h' });
56: }
57: 
58: /**
59:  * Verifies a local JWT and returns normalized claims.
60:  */
61: function verifyLocalToken(token: string) {
62:   const payload = jwt.verify(token, config.jwtSecret) as {
63:     sub: string;
64:     email: string;
65:     orgId?: string;
66:     role?: UserRole;
67:   };
68:   return {
69:     sub: payload.sub,
70:     email: payload.email,
71:     orgId: payload.orgId,
72:     role: payload.role || ('owner' as UserRole),
73:   };
74: }
75: 
76: // ---------------------------------------------------------------------------
77: // Internal service tokens (for agent-to-API calls within the platform)
78: // ---------------------------------------------------------------------------
79: const INTERNAL_TOKEN_SECRET = config.authMode === 'cognito'
80:   ? config.cognito.userPoolId
81:   : config.jwtSecret;
82: 
83: interface InternalTokenPayload {
84:   sub: string;
85:   email: string;
86:   orgId: string;
87:   role: UserRole;
88:   exp: number;
89: }
90: 
91: /**
92:  * Creates a short-lived HMAC-signed internal token for agent subprocess auth.
93:  */
94: export function createToken(claims: {
95:   userId: string;
96:   email: string;
97:   organizationId: string;
98:   role: UserRole;
99: }): string {
100:   const payload: InternalTokenPayload = {
101:     sub: claims.userId,
102:     email: claims.email,
103:     orgId: claims.organizationId,
104:     role: claims.role,
105:     exp: Math.floor(Date.now() / 1000) + 3600,
106:   };
107:   const data = Buffer.from(JSON.stringify(payload)).toString('base64url');
108:   const sig = crypto.createHmac('sha256', INTERNAL_TOKEN_SECRET).update(data).digest('base64url');
109:   return `internal.${data}.${sig}`;
110: }
111: 
112: /**
113:  * Verifies an internal service token. Returns null if invalid.
114:  */
115: function verifyInternalToken(token: string): InternalTokenPayload | null {
116:   const parts = token.split('.');
117:   if (parts.length !== 3 || parts[0] !== 'internal') return null;
118:   const data = parts[1]!;
119:   const sig = parts[2]!;
120:   const expected = crypto.createHmac('sha256', INTERNAL_TOKEN_SECRET).update(data).digest('base64url');
121:   if (sig !== expected) return null;
122:   try {
123:     const payload = JSON.parse(Buffer.from(data, 'base64url').toString()) as InternalTokenPayload;
124:     if (payload.exp < Math.floor(Date.now() / 1000)) return null;
125:     return payload;
126:   } catch (_e) {
127:     return null;
128:   }
129: }
130: 
131: // ---------------------------------------------------------------------------
132: // Main authenticate hook
133: // ---------------------------------------------------------------------------
134: 
135: /**
136:  * Authentication hook that extracts and validates a JWT from the
137:  * Authorization header (or ?token query param for iframe/img src).
138:  *
139:  * Supports both Cognito and local auth modes.
140:  */
141: export async function authenticate(request: FastifyRequest, reply: FastifyReply): Promise<void> {
142:   const authHeader = request.headers.authorization;
143:   const queryToken = (request.query as Record<string, string>)?.token;
144: 
145:   if (!authHeader && !queryToken) {
146:     return reply.status(401).send({
147:       error: 'Missing authorization header',
148:       code: 'UNAUTHORIZED',
149:       requestId: request.id,
150:     });
151:   }
152: 
153:   let token: string;
154: 
155:   if (authHeader) {
156:     if (!authHeader.startsWith('Bearer ')) {
157:       return reply.status(401).send({
158:         error: 'Invalid authorization format. Expected: Bearer <token>',
159:         code: 'UNAUTHORIZED',
160:         requestId: request.id,
161:       });
162:     }
163:     token = authHeader.substring(7);
164:   } else {
165:     token = queryToken!;
166:   }
167: 
168:   if (!token) {
169:     return reply.status(401).send({
170:       error: 'Missing token',
171:       code: 'UNAUTHORIZED',
172:       requestId: request.id,
173:     });
174:   }
175: 
176:   try {
177:     // Try internal service token first (for agent subprocess calls)
178:     const internalPayload = verifyInternalToken(token);
179:     if (internalPayload) {
180:       const user: User = {
181:         id: internalPayload.sub,
182:         email: internalPayload.email,
183:         orgId: internalPayload.orgId,
184:         role: internalPayload.role,
185:       };
186:       request.user = user;
187:       return;
188:     }
189: 
190:     // Verify token based on auth mode
191:     const claims = await verifyToken(token);
192: 
193:     // Look up profile by sub first, then fall back to email
194:     let profile = await prisma.profiles.findUnique({ where: { id: claims.sub } });
195: 
196:     if (!profile && config.authMode === 'cognito') {
197:       // First Cognito login — bind to existing profile by email (username field)
198:       profile = await prisma.profiles.findUnique({ where: { username: claims.email } });
199: 
200:       if (profile) {
201:         const oldId = profile.id;
202:         const migrations = [
203:           [`UPDATE memberships SET user_id = $1 WHERE user_id = $2`, claims.sub, oldId],
204:           [`UPDATE chat_sessions SET user_id = $1 WHERE user_id = $2`, claims.sub, oldId],
205:           [`UPDATE tasks SET created_by = $1 WHERE created_by = $2`, claims.sub, oldId],
206:           [`UPDATE workflows SET created_by = $1 WHERE created_by = $2`, claims.sub, oldId],
207:           [`UPDATE workflow_executions SET user_id = $1 WHERE user_id = $2`, claims.sub, oldId],
208:           [`UPDATE api_keys SET user_id = $1 WHERE user_id = $2`, claims.sub, oldId],
209:           [`UPDATE skill_votes SET user_id = $1 WHERE user_id = $2`, claims.sub, oldId],
210:         ] as const;
211: 
212:         for (const [sql, newId, prevId] of migrations) {
213:           try {
214:             await prisma.$executeRawUnsafe(sql, newId, prevId);
215:           } catch (_e) { /* Table may not exist */ }
216:         }
217: 
218:         await prisma.$executeRawUnsafe(
219:           `UPDATE profiles SET id = $1 WHERE id = $2`,
220:           claims.sub, oldId,
221:         );
222:         profile = await prisma.profiles.findUnique({ where: { id: claims.sub } });
223:         request.log.info({ oldId, newId: claims.sub }, 'Migrated user ID to Cognito sub');
224:       }
225:     }
226: 
227:     if (!profile) {
228:       return reply.status(401).send({
229:         error: 'No profile found for this user. Contact your administrator.',
230:         code: 'UNAUTHORIZED',
231:         requestId: request.id,
232:       });
233:     }
234: 
235:     const membership = await prisma.memberships.findFirst({
236:       where: { user_id: claims.sub },
237:     });
238: 
239:     const user: User = {
240:       id: claims.sub,
241:       email: claims.email,
242:       orgId: membership?.organization_id ?? claims.orgId ?? '',
243:       role: (membership?.role as UserRole) ?? claims.role ?? 'owner',
244:     };
245: 
246:     request.user = user;
247:   } catch (error) {
248:     request.log.error({ err: error }, 'Token verification failed');
249:     return reply.status(401).send({
250:       error: 'Invalid or expired token',
251:       code: 'UNAUTHORIZED',
252:       requestId: request.id,
253:     });
254:   }
255: }
256: 
257: // ---------------------------------------------------------------------------
258: // Role-based access control
259: // ---------------------------------------------------------------------------
260: 
261: export function requireRole(...roles: UserRole[]) {
262:   return async (request: FastifyRequest, reply: FastifyReply): Promise<void> => {
263:     if (!request.user) {
264:       return reply.status(403).send({
265:         error: 'Access denied. Authentication required.',
266:         code: 'FORBIDDEN',
267:         requestId: request.id,
268:       });
269:     }
270:     if (!roles.includes(request.user.role)) {
271:       return reply.status(403).send({
272:         error: `Access denied. Required role: ${roles.join(' or ')}`,
273:         code: 'FORBIDDEN',
274:         requestId: request.id,
275:       });
276:     }
277:   };
278: }
279: 
280: export const requireModifyAccess = requireRole('owner', 'admin', 'member');
281: export const requireAdminAccess = requireRole('owner', 'admin');
282: export const requireOwnerAccess = requireRole('owner');

