1: /**
2:  * Authorization Middleware Factories
3:  *
4:  * Fastify preHandler factories that integrate the AuthorizationService
5:  * with route-level permission enforcement.
6:  *
7:  * Usage:
8:  *   fastify.delete('/agents/:id', {
9:  *     preHandler: [authenticate, requirePermission('agents:delete')],
10:  *   }, handler)
11:  *
12:  *   // With resource ownership check (resourceOwnerId resolved at request time):
13:  *   fastify.delete('/agents/:id', {
14:  *     preHandler: [
15:  *       authenticate,
16:  *       requirePermission('agents:delete', async (req) => ({
17:  *         resourceOwnerId: await getAgentOwner(req.params.id),
18:  *       })),
19:  *     ],
20:  *   }, handler)
21:  */
22: 
23: import type { FastifyRequest, FastifyReply } from 'fastify';
24: import { authorizationService, type AuthorizationContext } from './authorization.js';
25: import type { Permission } from './permissions.js';
26: 
27: type ContextResolver = (
28:   request: FastifyRequest
29: ) => AuthorizationContext | Promise<AuthorizationContext>;
30: 
31: /**
32:  * Creates a Fastify preHandler that enforces a single permission.
33:  * Optionally accepts a context resolver to supply resource ownership info.
34:  */
35: export function requirePermission(permission: Permission, resolveCtx?: ContextResolver) {
36:   return async (request: FastifyRequest, reply: FastifyReply): Promise<void> => {
37:     if (!request.user) {
38:       return reply.status(401).send({
39:         error: 'Authentication required',
40:         code: 'UNAUTHORIZED',
41:         requestId: request.id,
42:       });
43:     }
44: 
45:     try {
46:       const ctx = resolveCtx ? await resolveCtx(request) : undefined;
47:       authorizationService.authorize(request.user, permission, ctx);
48:     } catch (err: unknown) {
49:       const message =
50:         err instanceof Error ? err.message : 'You do not have permission to perform this action.';
51:       return reply.status(403).send({
52:         error: message,
53:         code: 'FORBIDDEN',
54:         requestId: request.id,
55:       });
56:     }
57:   };
58: }
59: 
60: /**
61:  * Creates a Fastify preHandler that requires ALL listed permissions.
62:  */
63: export function requireAllPermissions(permissions: Permission[], resolveCtx?: ContextResolver) {
64:   return async (request: FastifyRequest, reply: FastifyReply): Promise<void> => {
65:     if (!request.user) {
66:       return reply.status(401).send({
67:         error: 'Authentication required',
68:         code: 'UNAUTHORIZED',
69:         requestId: request.id,
70:       });
71:     }
72: 
73:     try {
74:       const ctx = resolveCtx ? await resolveCtx(request) : undefined;
75:       for (const permission of permissions) {
76:         authorizationService.authorize(request.user, permission, ctx);
77:       }
78:     } catch (err: unknown) {
79:       const message =
80:         err instanceof Error ? err.message : 'You do not have permission to perform this action.';
81:       return reply.status(403).send({
82:         error: message,
83:         code: 'FORBIDDEN',
84:         requestId: request.id,
85:       });
86:     }
87:   };
88: }
89: 
90: /**
91:  * Creates a Fastify preHandler that requires AT LEAST ONE of the listed permissions.
92:  */
93: export function requireAnyPermission(permissions: Permission[], resolveCtx?: ContextResolver) {
94:   return async (request: FastifyRequest, reply: FastifyReply): Promise<void> => {
95:     if (!request.user) {
96:       return reply.status(401).send({
97:         error: 'Authentication required',
98:         code: 'UNAUTHORIZED',
99:         requestId: request.id,
100:       });
101:     }
102: 
103:     const ctx = resolveCtx ? await resolveCtx(request) : undefined;
104:     const hasAny = authorizationService.canAny(request.user, permissions, ctx);
105: 
106:     if (!hasAny) {
107:       return reply.status(403).send({
108:         error: `You need one of the following permissions: ${permissions.join(', ')}`,
109:         code: 'FORBIDDEN',
110:         requestId: request.id,
111:       });
112:     }
113:   };
114: }

