1: /**
2:  * Authorization Service
3:  *
4:  * Provides fine-grained, resource-level permission checks on top of the
5:  * existing role-based access control system.
6:  *
7:  * Usage:
8:  *   authorizationService.authorize(user, 'agents:delete', { resourceOwnerId })
9:  *   authorizationService.can(user, 'workflows:execute')
10:  */
11: 
12: import { AppError } from '../middleware/errorHandler.js';
13: import type { User, UserRole } from '../types/index.js';
14: import {
15:   PERMISSIONS_BY_ROLE,
16:   OWNER_ONLY_PERMISSIONS,
17:   OWNERSHIP_BYPASS_ROLES,
18:   type Permission,
19: } from './permissions.js';
20: 
21: // ─── Types ───────────────────────────────────────────────────────────────────
22: 
23: export interface AuthorizationContext {
24:   /** The user ID of the resource owner (for ownership-restricted permissions). */
25:   resourceOwnerId?: string;
26:   /** Optional org ID to verify the resource belongs to the user's org. */
27:   resourceOrgId?: string;
28: }
29: 
30: // ─── Service ─────────────────────────────────────────────────────────────────
31: 
32: export class AuthorizationService {
33:   /**
34:    * Check if a user has a permission, returning a boolean.
35:    * Does not throw — use this for conditional UI/logic branching.
36:    */
37:   can(user: User, permission: Permission, ctx?: AuthorizationContext): boolean {
38:     const rolePermissions = PERMISSIONS_BY_ROLE[user.role];
39:     if (!rolePermissions) return false;
40: 
41:     // Check base role permission
42:     if (!rolePermissions.has(permission)) return false;
43: 
44:     // If the permission is ownership-restricted and the user's role doesn't
45:     // bypass ownership checks, verify they own the resource.
46:     if (
47:       OWNER_ONLY_PERMISSIONS.has(permission) &&
48:       !OWNERSHIP_BYPASS_ROLES.has(user.role) &&
49:       ctx?.resourceOwnerId !== undefined
50:     ) {
51:       return user.id === ctx.resourceOwnerId;
52:     }
53: 
54:     // Verify resource belongs to the user's org (if provided)
55:     if (ctx?.resourceOrgId !== undefined && ctx.resourceOrgId !== user.orgId) {
56:       return false;
57:     }
58: 
59:     return true;
60:   }
61: 
62:   /**
63:    * Assert that a user has a permission.
64:    * Throws AppError.forbidden if the check fails.
65:    */
66:   authorize(user: User, permission: Permission, ctx?: AuthorizationContext): void {
67:     if (!this.can(user, permission, ctx)) {
68:       const [resource, action] = permission.split(':');
69:       throw AppError.forbidden(
70:         `You do not have permission to ${action} ${resource}.`
71:       );
72:     }
73:   }
74: 
75:   /**
76:    * Check multiple permissions at once (AND logic — all must pass).
77:    */
78:   canAll(user: User, permissions: Permission[], ctx?: AuthorizationContext): boolean {
79:     return permissions.every((p) => this.can(user, p, ctx));
80:   }
81: 
82:   /**
83:    * Check multiple permissions at once (OR logic — at least one must pass).
84:    */
85:   canAny(user: User, permissions: Permission[], ctx?: AuthorizationContext): boolean {
86:     return permissions.some((p) => this.can(user, p, ctx));
87:   }
88: 
89:   /**
90:    * Returns all permissions granted to a role.
91:    */
92:   getPermissionsForRole(role: UserRole): Permission[] {
93:     return Array.from(PERMISSIONS_BY_ROLE[role] ?? []);
94:   }
95: }
96: 
97: export const authorizationService = new AuthorizationService();

