1: /**
2:  * Authorization Permission Definitions
3:  *
4:  * Defines the resource:action permission matrix for each role.
5:  * Roles are hierarchical: owner > admin > member > viewer
6:  */
7: 
8: import type { UserRole } from '../types/index.js';
9: 
10: // ─── Permission Types ────────────────────────────────────────────────────────
11: 
12: export type Resource =
13:   | 'agents'
14:   | 'workflows'
15:   | 'skills'
16:   | 'members'
17:   | 'organization'
18:   | 'api_keys'
19:   | 'tasks'
20:   | 'documents'
21:   | 'integrations';
22: 
23: export type Action = 'read' | 'write' | 'delete' | 'execute' | 'invite' | 'publish' | 'remove';
24: 
25: export type Permission = `${Resource}:${Action}`;
26: 
27: // ─── Role Permission Matrix ──────────────────────────────────────────────────
28: 
29: /**
30:  * Permissions granted to each role.
31:  * Higher roles inherit all permissions from lower roles.
32:  */
33: const ROLE_PERMISSIONS: Record<UserRole, Permission[]> = {
34:   viewer: [
35:     'agents:read',
36:     'workflows:read',
37:     'skills:read',
38:     'members:read',
39:     'organization:read',
40:     'tasks:read',
41:     'documents:read',
42:     'integrations:read',
43:   ],
44: 
45:   member: [
46:     // inherits viewer
47:     'agents:write',
48:     'agents:delete',   // own resources only — enforced in AuthorizationService
49:     'workflows:write',
50:     'workflows:delete', // own resources only
51:     'workflows:execute',
52:     'skills:write',
53:     'tasks:write',
54:     'tasks:delete',    // own resources only
55:     'documents:write',
56:     'documents:delete', // own resources only
57:     'api_keys:read',
58:     'api_keys:write',
59:     'api_keys:delete', // own resources only
60:   ],
61: 
62:   admin: [
63:     // inherits member
64:     'members:invite',
65:     'members:update',
66:     'members:remove',
67:     'organization:update',
68:     'skills:publish',
69:     'integrations:write',
70:     'integrations:delete',
71:   ],
72: 
73:   owner: [
74:     // inherits admin
75:     'organization:delete',
76:   ],
77: };
78: 
79: // ─── Resolved Permission Sets ────────────────────────────────────────────────
80: 
81: const ROLE_HIERARCHY: UserRole[] = ['viewer', 'member', 'admin', 'owner'];
82: 
83: /**
84:  * Builds the full permission set for a role by accumulating all permissions
85:  * from lower roles in the hierarchy.
86:  */
87: function buildPermissionSet(role: UserRole): Set<Permission> {
88:   const set = new Set<Permission>();
89:   for (const r of ROLE_HIERARCHY) {
90:     for (const p of ROLE_PERMISSIONS[r]) {
91:       set.add(p);
92:     }
93:     if (r === role) break;
94:   }
95:   return set;
96: }
97: 
98: export const PERMISSIONS_BY_ROLE: Record<UserRole, Set<Permission>> = {
99:   viewer: buildPermissionSet('viewer'),
100:   member: buildPermissionSet('member'),
101:   admin: buildPermissionSet('admin'),
102:   owner: buildPermissionSet('owner'),
103: };
104: 
105: /**
106:  * Permissions that are restricted to the resource owner even when the role
107:  * grants them. Admins and owners bypass this check.
108:  */
109: export const OWNER_ONLY_PERMISSIONS = new Set<Permission>([
110:   'agents:delete',
111:   'workflows:delete',
112:   'tasks:delete',
113:   'documents:delete',
114:   'api_keys:delete',
115: ]);
116: 
117: /**
118:  * Roles that bypass resource ownership checks (can act on any resource).
119:  */
120: export const OWNERSHIP_BYPASS_ROLES = new Set<UserRole>(['admin', 'owner']);

