1: /**
2:  * Authentication Routes
3:  *
4:  * Supports two modes:
5:  * - cognito: Cognito Hosted UI handles login; backend verifies tokens
6:  * - local: Backend handles login/register with username/password + JWT
7:  */
8: 
9: import { FastifyInstance, FastifyRequest, FastifyReply } from 'fastify';
10: import { verifyToken, createLocalJwt } from '../middleware/auth.js';
11: import { prisma } from '../config/database.js';
12: import { config } from '../config/index.js';
13: import bcrypt from 'bcryptjs';
14: import { v4 as uuidv4 } from 'uuid';
15: 
16: export async function authRoutes(fastify: FastifyInstance): Promise<void> {
17:   /**
18:    * GET /auth/config
19:    * Returns auth configuration for the frontend (public, no auth required).
20:    */
21:   fastify.get(
22:     '/config',
23:     {
24:       schema: {
25:         description: 'Get auth configuration for frontend',
26:         tags: ['auth'],
27:       },
28:     },
29:     async (_request: FastifyRequest, reply: FastifyReply) => {
30:       if (config.authMode === 'cognito') {
31:         return reply.send({
32:           authMode: 'cognito',
33:           userPoolId: config.cognito.userPoolId,
34:           clientId: config.cognito.clientId,
35:           region: config.cognito.region,
36:           domain: config.cognito.domain,
37:         });
38:       }
39:       return reply.send({ authMode: 'local' });
40:     },
41:   );
42: 
43:   /**
44:    * POST /auth/login (local mode only)
45:    * Authenticates with username/password and returns a JWT.
46:    */
47:   fastify.post(
48:     '/login',
49:     {
50:       schema: {
51:         description: 'Login with username and password (local auth mode)',
52:         tags: ['auth'],
53:         body: {
54:           type: 'object',
55:           required: ['username', 'password'],
56:           properties: {
57:             username: { type: 'string' },
58:             password: { type: 'string' },
59:           },
60:         },
61:       },
62:     },
63:     async (request: FastifyRequest<{ Body: { username: string; password: string } }>, reply: FastifyReply) => {
64:       if (config.authMode !== 'local') {
65:         return reply.status(400).send({ error: 'Local auth is not enabled. Use Cognito.' });
66:       }
67: 
68:       const { username, password } = request.body;
69: 
70:       const profile = await prisma.profiles.findUnique({ where: { username } });
71:       if (!profile || !profile.password_hash) {
72:         return reply.status(401).send({ error: 'Invalid username or password' });
73:       }
74: 
75:       const valid = await bcrypt.compare(password, profile.password_hash);
76:       if (!valid) {
77:         return reply.status(401).send({ error: 'Invalid username or password' });
78:       }
79: 
80:       const membership = await prisma.memberships.findFirst({
81:         where: { user_id: profile.id },
82:       });
83: 
84:       const token = createLocalJwt({
85:         sub: profile.id,
86:         email: profile.username,
87:         orgId: membership?.organization_id ?? '',
88:         role: (membership?.role as any) ?? 'owner',
89:       });
90: 
91:       return reply.send({
92:         token,
93:         user: {
94:           id: profile.id,
95:           email: profile.username,
96:           name: profile.full_name || profile.username,
97:           organizationId: membership?.organization_id,
98:           role: membership?.role,
99:         },
100:       });
101:     },
102:   );
103: 
104:   /**
105:    * POST /auth/register (local mode only)
106:    * Creates a new user with username/password.
107:    * First user becomes owner of a new default organization.
108:    */
109:   fastify.post(
110:     '/register',
111:     {
112:       schema: {
113:         description: 'Register a new user (local auth mode)',
114:         tags: ['auth'],
115:         body: {
116:           type: 'object',
117:           required: ['username', 'password'],
118:           properties: {
119:             username: { type: 'string' },
120:             password: { type: 'string' },
121:             fullName: { type: 'string' },
122:           },
123:         },
124:       },
125:     },
126:     async (request: FastifyRequest<{ Body: { username: string; password: string; fullName?: string } }>, reply: FastifyReply) => {
127:       if (config.authMode !== 'local') {
128:         return reply.status(400).send({ error: 'Local auth is not enabled. Use Cognito.' });
129:       }
130: 
131:       const { username, password, fullName } = request.body;
132: 
133:       // Check if username already exists
134:       const existing = await prisma.profiles.findUnique({ where: { username } });
135:       if (existing) {
136:         return reply.status(409).send({ error: 'Username already exists' });
137:       }
138: 
139:       const passwordHash = await bcrypt.hash(password, 10);
140:       const userId = uuidv4();
141: 
142:       // Create profile
143:       const profile = await prisma.profiles.create({
144:         data: {
145:           id: userId,
146:           username,
147:           full_name: fullName || username,
148:           password_hash: passwordHash,
149:         },
150:       });
151: 
152:       // Find or create a default organization
153:       let org = await prisma.organizations.findFirst({ orderBy: { created_at: 'asc' } });
154:       if (!org) {
155:         org = await prisma.organizations.create({
156:           data: {
157:             id: uuidv4(),
158:             name: 'Default Organization',
159:             slug: 'default',
160:           },
161:         });
162:       }
163: 
164:       // Create membership
165:       const memberCount = await prisma.memberships.count({
166:         where: { organization_id: org.id },
167:       });
168:       const role = memberCount === 0 ? 'owner' : 'member';
169: 
170:       await prisma.memberships.create({
171:         data: {
172:           id: uuidv4(),
173:           user_id: userId,
174:           organization_id: org.id,
175:           role,
176:         },
177:       });
178: 
179:       const token = createLocalJwt({
180:         sub: userId,
181:         email: username,
182:         orgId: org.id,
183:         role: role as any,
184:       });
185: 
186:       return reply.send({
187:         token,
188:         user: {
189:           id: userId,
190:           email: username,
191:           name: fullName || username,
192:           organizationId: org.id,
193:           role,
194:         },
195:       });
196:     },
197:   );
198: 
199:   /**
200:    * GET /auth/me
201:    * Returns the current user's information from a verified token.
202:    */
203:   fastify.get(
204:     '/me',
205:     {
206:       schema: {
207:         description: 'Get current user information',
208:         tags: ['auth'],
209:         security: [{ bearerAuth: [] }],
210:       },
211:     },
212:     async (request: FastifyRequest, reply: FastifyReply) => {
213:       const authHeader = request.headers.authorization;
214:       if (!authHeader?.startsWith('Bearer ')) {
215:         return reply.status(401).send({
216:           error: 'Missing or invalid authorization header',
217:           code: 'UNAUTHORIZED',
218:         });
219:       }
220: 
221:       const token = authHeader.substring(7);
222: 
223:       try {
224:         const claims = await verifyToken(token);
225: 
226:         let profile = await prisma.profiles.findUnique({
227:           where: { id: claims.sub },
228:         });
229: 
230:         if (!profile) {
231:           profile = await prisma.profiles.findUnique({
232:             where: { username: claims.email },
233:           });
234:         }
235: 
236:         if (!profile) {
237:           return reply.status(404).send({
238:             error: 'User profile not found',
239:             code: 'NOT_FOUND',
240:           });
241:         }
242: 
243:         const membership = await prisma.memberships.findFirst({
244:           where: { user_id: profile.id },
245:           include: { organization: true },
246:         });
247: 
248:         return reply.send({
249:           id: profile.id,
250:           email: profile.username || claims.email,
251:           name: profile.full_name || profile.username || 'Unknown',
252:           organizationId: membership?.organization_id,
253:           organizationName: membership?.organization.name,
254:           role: membership?.role,
255:         });
256:       } catch (error) {
257:         return reply.status(401).send({
258:           error: 'Invalid token',
259:           code: 'UNAUTHORIZED',
260:         });
261:       }
262:     },
263:   );
264: 
265:   /**
266:    * GET /auth/invite/:token
267:    * Validates an invite token and returns invite details (public, no auth).
268:    */
269:   fastify.get(
270:     '/invite/:token',
271:     {
272:       schema: {
273:         description: 'Validate an invite token',
274:         tags: ['auth'],
275:         params: {
276:           type: 'object',
277:           required: ['token'],
278:           properties: { token: { type: 'string' } },
279:         },
280:       },
281:     },
282:     async (request: FastifyRequest<{ Params: { token: string } }>, reply: FastifyReply) => {
283:       const { token } = request.params;
284: 
285:       const membership = await prisma.memberships.findUnique({
286:         where: { invite_token: token },
287:         include: { organization: true },
288:       });
289: 
290:       if (!membership) {
291:         return reply.status(404).send({ error: 'Invalid or expired invite link' });
292:       }
293: 
294:       if (membership.status !== 'pending') {
295:         return reply.status(400).send({ error: 'This invitation has already been accepted' });
296:       }
297: 
298:       if (membership.invite_expires_at && new Date() > membership.invite_expires_at) {
299:         return reply.status(410).send({ error: 'This invitation has expired' });
300:       }
301: 
302:       return reply.send({
303:         email: membership.invited_email,
304:         role: membership.role,
305:         organizationName: membership.organization.name,
306:       });
307:     },
308:   );
309: 
310:   /**
311:    * POST /auth/accept-invite
312:    * Accepts an invite: creates user account and activates membership.
313:    */
314:   fastify.post(
315:     '/accept-invite',
316:     {
317:       schema: {
318:         description: 'Accept an invitation and create account',
319:         tags: ['auth'],
320:         body: {
321:           type: 'object',
322:           required: ['token', 'password'],
323:           properties: {
324:             token: { type: 'string' },
325:             password: { type: 'string', minLength: 8 },
326:             fullName: { type: 'string' },
327:           },
328:         },
329:       },
330:     },
331:     async (request: FastifyRequest<{ Body: { token: string; password: string; fullName?: string } }>, reply: FastifyReply) => {
332:       const { token, password, fullName } = request.body;
333: 
334:       const membership = await prisma.memberships.findUnique({
335:         where: { invite_token: token },
336:         include: { organization: true },
337:       });
338: 
339:       if (!membership) {
340:         return reply.status(404).send({ error: 'Invalid or expired invite link' });
341:       }
342: 
343:       if (membership.status !== 'pending') {
344:         return reply.status(400).send({ error: 'This invitation has already been accepted' });
345:       }
346: 
347:       if (membership.invite_expires_at && new Date() > membership.invite_expires_at) {
348:         return reply.status(410).send({ error: 'This invitation has expired' });
349:       }
350: 
351:       const email = membership.invited_email!;
352: 
353:       // Check if a profile already exists for this email
354:       const existingProfile = await prisma.profiles.findUnique({ where: { username: email } });
355:       if (existingProfile) {
356:         return reply.status(409).send({ error: 'An account with this email already exists. Please sign in.' });
357:       }
358: 
359:       // Create profile with password
360:       const passwordHash = await bcrypt.hash(password, 10);
361:       const userId = uuidv4();
362: 
363:       await prisma.profiles.create({
364:         data: {
365:           id: userId,
366:           username: email,
367:           full_name: fullName || email,
368:           password_hash: passwordHash,
369:         },
370:       });
371: 
372:       // Activate membership
373:       await prisma.memberships.update({
374:         where: { id: membership.id },
375:         data: {
376:           user_id: userId,
377:           status: 'active',
378:           invite_token: null,
379:           invite_expires_at: null,
380:         },
381:       });
382: 
383:       // Return a JWT so the user is logged in immediately
384:       const jwt = createLocalJwt({
385:         sub: userId,
386:         email,
387:         orgId: membership.organization_id,
388:         role: membership.role as any,
389:       });
390: 
391:       return reply.send({
392:         token: jwt,
393:         user: {
394:           id: userId,
395:           email,
396:           name: fullName || email,
397:           organizationId: membership.organization_id,
398:           organizationName: membership.organization.name,
399:           role: membership.role,
400:         },
401:       });
402:     },
403:   );
404: }

