13: 
14: /**
15:  * Validation schemas
16:  */
17: const uploadUrlSchema = z.object({
18:   fileName: z.string().min(1, 'File name is required'),
19:   contentType: z.string().min(1, 'Content type is required'),
20: });
21: 
22: const fileKeyParamSchema = z.object({
23:   key: z.string().min(1, 'File key is required'),
24: });
25: 
26: /**
27:  * Request types for route handlers
