48: /**
49:  * Parse and validate Zod schema, throwing AppError on failure
50:  */
51: function validateSchema<T>(schema: { parse: (data: unknown) => T }, data: unknown): T {
52:   try {
53:     return schema.parse(data);
54:   } catch (error) {
55:     if (error instanceof ZodError) {
56:       throw AppError.validation('Validation failed', error.issues);
57:     }
58:     throw error;
59:   }
60: }
