62: /**
63:  * Register file routes on the Fastify instance.
64:  * All routes require authentication and enforce organization-based file isolation.
65:  */
66: export async function fileRoutes(fastify: FastifyInstance): Promise<void> {
67:   /**
68:    * POST /api/files/upload-url
69:    * Get a presigned URL for uploading a file to S3.
70:    * Files are stored with organization_id prefix for isolation.
71:    * Requirements: 12.1, 12.3
72:    */
73:   fastify.post<GetUploadUrlRequest>(
74:     '/upload-url',
75:     {
76:       preHandler: [authenticate, requireModifyAccess],
77:       schema: {
78:         description: 'Get a presigned URL for uploading a file to S3',
79:         tags: ['Files'],
80:         security: [{ bearerAuth: [] }],
81:         body: {
82:           type: 'object',
83:           required: ['fileName', 'contentType'],
84:           properties: {
85:             fileName: { type: 'string', minLength: 1, description: 'Original file name' },
86:             contentType: { type: 'string', minLength: 1, description: 'MIME type of the file' },
87:           },
88:         },
89:         response: {
90:           200: {
91:             type: 'object',
92:             properties: {
93:               url: { type: 'string', description: 'Presigned upload URL' },
94:               key: { type: 'string', description: 'S3 key for the file' },
95:               expiresIn: { type: 'integer', description: 'URL expiration time in seconds' },
96:             },
97:           },
98:           400: {
99:             type: 'object',
100:             properties: {
101:               error: { type: 'string' },
102:               code: { type: 'string' },
103:               details: { type: 'array' },
104:               requestId: { type: 'string' },
105:             },
106:           },
107:         },
108:       },
109:     },
110:     async (request: FastifyRequest<GetUploadUrlRequest>, reply: FastifyReply) => {
111:       const { fileName, contentType } = validateSchema(uploadUrlSchema, request.body);
112: 
113:       const result = await fileService.getUploadUrl(request.user!.orgId, fileName, contentType);
