123:    * Requirements: 12.2, 12.3, 12.4
124:    */
125:   fastify.get<GetDownloadUrlRequest>(
126:     '/:key',
127:     {
128:       preHandler: [authenticate],
129:       schema: {
130:         description: 'Get a presigned URL for downloading a file from S3',
131:         tags: ['Files'],
132:         security: [{ bearerAuth: [] }],
133:         params: {
134:           type: 'object',
135:           required: ['key'],
136:           properties: {
137:             key: { type: 'string', minLength: 1, description: 'S3 key of the file' },
138:           },
139:         },
140:         response: {
141:           200: {
142:             type: 'object',
143:             properties: {
144:               url: { type: 'string', description: 'Presigned download URL' },
145:               key: { type: 'string', description: 'S3 key of the file' },
146:               expiresIn: { type: 'integer', description: 'URL expiration time in seconds' },
147:             },
148:           },
149:           403: {
150:             type: 'object',
151:             properties: {
152:               error: { type: 'string' },
153:               code: { type: 'string' },
154:               requestId: { type: 'string' },
155:             },
156:           },
157:           404: {
158:             type: 'object',
159:             properties: {
160:               error: { type: 'string' },
161:               code: { type: 'string' },
162:               requestId: { type: 'string' },
163:             },
164:           },
165:         },
166:       },
167:     },
168:     async (request: FastifyRequest<GetDownloadUrlRequest>, reply: FastifyReply) => {
169:       // Decode the URL-encoded key parameter
170:       const key = decodeURIComponent(request.params.key);
171:       validateSchema(fileKeyParamSchema, { key });
172: 
173:       const result = await fileService.getDownloadUrl(key, request.user!.orgId);
174: 
175:       return reply.status(200).send(result);
176:     }
177:   );
178: 
179:   /**
180:    * GET /api/files/:key/metadata
181:    * Get metadata for a file in S3.
182:    * Validates that the file belongs to the user's organization.
183:    * Requirements: 12.3, 12.4
184:    */
185:   fastify.get<GetFileMetadataRequest>(
186:     '/:key/metadata',
187:     {
188:       preHandler: [authenticate],
189:       schema: {
190:         description: 'Get metadata for a file in S3',
191:         tags: ['Files'],
192:         security: [{ bearerAuth: [] }],
193:         params: {
194:           type: 'object',
195:           required: ['key'],
196:           properties: {
197:             key: { type: 'string', minLength: 1, description: 'S3 key of the file' },
198:           },
199:         },
200:         response: {
201:           200: {
202:             type: 'object',
203:             properties: {
204:               key: { type: 'string', description: 'S3 key of the file' },
205:               contentType: { type: 'string', nullable: true, description: 'MIME type of the file' },
206:               contentLength: { type: 'integer', nullable: true, description: 'File size in bytes' },
207:               lastModified: {
208:                 type: 'string',
209:                 nullable: true,
210:                 description: 'Last modification timestamp',
211:               },
212:             },
213:           },
214:           403: {
215:             type: 'object',
216:             properties: {
217:               error: { type: 'string' },
218:               code: { type: 'string' },
219:               requestId: { type: 'string' },
220:             },
221:           },
222:           404: {
223:             type: 'object',
224:             properties: {
225:               error: { type: 'string' },
226:               code: { type: 'string' },
227:               requestId: { type: 'string' },
228:             },
229:           },
230:         },
231:       },
232:     },
233:     async (request: FastifyRequest<GetFileMetadataRequest>, reply: FastifyReply) => {
234:       // Decode the URL-encoded key parameter
235:       const key = decodeURIComponent(request.params.key);
236:       validateSchema(fileKeyParamSchema, { key });
237: 
238:       const metadata = await fileService.getFileMetadata(key, request.user!.orgId);
239: 
240:       return reply.status(200).send(metadata);
241:     }
242:   );
243: 
244:   /**
245:    * DELETE /api/files/:key
246:    * Delete a file from S3.
247:    * Validates that the file belongs to the user's organization.
248:    * Requirements: 12.3, 12.4
249:    */
250:   fastify.delete<DeleteFileRequest>(
251:     '/:key',
252:     {
253:       preHandler: [authenticate, requireModifyAccess],
254:       schema: {
255:         description: 'Delete a file from S3',
256:         tags: ['Files'],
257:         security: [{ bearerAuth: [] }],
258:         params: {
259:           type: 'object',
260:           required: ['key'],
261:           properties: {
262:             key: { type: 'string', minLength: 1, description: 'S3 key of the file' },
263:           },
264:         },
265:         response: {
266:           204: {
267:             type: 'null',
268:             description: 'File deleted successfully',
269:           },
270:           403: {
271:             type: 'object',
272:             properties: {
273:               error: { type: 'string' },
274:               code: { type: 'string' },
275:               requestId: { type: 'string' },
276:             },
277:           },
278:         },
279:       },
280:     },
281:     async (request: FastifyRequest<DeleteFileRequest>, reply: FastifyReply) => {
282:       // Decode the URL-encoded key parameter
283:       const key = decodeURIComponent(request.params.key);
284:       validateSchema(fileKeyParamSchema, { key });
285: 
286:       await fileService.deleteFile(key, request.user!.orgId);
287: 
288:       return reply.status(204).send();
289:     }
290:   );
291: }

