137:   /** Per-session workspace: {baseDir}/{orgId}/{scopeId}/sessions/{sessionId}/ */
138:   getSessionWorkspacePath(orgId: string, scopeId: string, sessionId: string): string {
139:     return join(this.baseDir, orgId, scopeId, 'sessions', sessionId);
140:   }
141: 
142:   /** Legacy per-agent workspace path (kept for backward compat). */
143:   getWorkspacePath(agentId: string): string {
144:     return join(this.baseDir, agentId);
