155:   /**
156:    * Resolve the backend URL that the agent can use to call back to the API.
157:    * - In local (claude) mode: localhost
158:    * - In agentcore/openclaw mode: the configured external backend URL
159:    */
160:   private resolveBackendUrl(): string {
161:     if (config.agentRuntime === 'agentcore' || config.agentRuntime === 'openclaw') {
162:       // AgentCore containers cannot reach localhost — use the external backend URL
163:       const externalUrl = config.agentcore.backendApiUrl
164:         || process.env.PUBLIC_API_URL
165:         || process.env.API_BASE_URL;
166:       if (externalUrl) return externalUrl;
167:       console.warn('[workspace-manager] AgentCore mode but no AGENTCORE_BACKEND_API_URL configured — RAG skill will use localhost (likely broken in container)');
168:     }
169:     return `http://localhost:${process.env.PORT || 3001}`;
170:   }
171: 
172:   /**
173:    * Build the knowledge-search skill markdown content.
174:    * Includes auth instructions so the agent can authenticate API calls.
175:    * Supports both knowledge_base_ids (new) and scope_id (legacy fallback).
176:    */
177:   private buildRagSkillContent(backendUrl: string, opts: { knowledgeBaseIds?: string[]; scopeId?: string }): string {
178:     const isRemote = config.agentRuntime === 'agentcore' || config.agentRuntime === 'openclaw';
179: 
180:     // Determine query parameter
181:     let queryParam: string;
182:     if (opts.knowledgeBaseIds && opts.knowledgeBaseIds.length > 0) {
183:       queryParam = `knowledge_base_ids=${opts.knowledgeBaseIds.join(',')}`;
184:     } else if (opts.scopeId) {
185:       queryParam = `scope_id=${opts.scopeId}`;
186:     } else {
187:       return ''; // No knowledge source configured
188:     }
189: 
190:     const lines = [
191:       '# Knowledge Search',
192:       '',
193:       'Use this skill to search the knowledge base for relevant document passages.',
194:       'This performs semantic similarity search — much more accurate than grep for finding relevant information.',
195:       '',
196:       '## When to Use',
197:       '- User asks about specific policies, procedures, or regulations',
198:       '- User needs information that might be in uploaded documents',
199:       '- You need to cite or reference specific document content',
200:       '- Grep/ripgrep returns too many or irrelevant results',
201:       '',
202:       '## How to Use',
203:       '',
204:     ];
205: 
206:     if (isRemote) {
207:       // In AgentCore mode, the agent needs to use curl/fetch with auth header
208:       lines.push(
209:         'Run a shell command to call the RAG API:',
210:         '',
211:         '```bash',
212:         `curl -s -H "Authorization: Bearer $AUTH_TOKEN" "${backendUrl}/api/rag/search?${queryParam}&q={URL_ENCODED_QUERY}&top_k=5"`,
213:         '```',
214:         '',
215:         'The `AUTH_TOKEN` environment variable is pre-configured with a valid authentication token.',
216:         '',
217:       );
218:     } else {
219:       // Local mode — use WebFetch (no auth needed as it goes through localhost)
220:       lines.push(
221:         `Use the WebFetch tool to call: ${backendUrl}/api/rag/search?${queryParam}&q={URL_ENCODED_QUERY}&top_k=5`,
222:         '',
223:       );
224:     }
225: 
226:     lines.push(
227:       '## Response Format',
228:       'JSON with a `data` array. Each result contains:',
229:       '- `filename`: source document name',
230:       '- `content`: relevant text passage (~500 tokens)',
231:       '- `similarity`: relevance score (0-1, higher is better)',
232:       '- `chunkIndex`: position within the document',
233:       '',
234:       '## Tips',
235:       '- Use natural language queries, not keywords',
236:       '- If the first search is not specific enough, refine your query',
237:       '- Always cite the source filename when using retrieved information',
238:       '',
239:     );
240: 
241:     return lines.join('\n');
242:   }
