248:   /**
249:    * Provision a brand-new session workspace with all scope artifacts.
250:    * Called once when a chat session is first created.
251:    */
252:   async ensureSessionWorkspace(
253:     orgId: string,
254:     sessionId: string,
255:     scope: ScopeForWorkspace,
256:     selectedAgentId: string | null,
257:     userId?: string,
258:   ): Promise<{ workspacePath: string; pluginPaths: string[] }> {
259:     const workspacePath = this.getSessionWorkspacePath(orgId, scope.id, sessionId);
260: 
261:     // Create directory structure (must complete before parallel writes)
262:     const skillsDir = join(workspacePath, '.claude', 'skills');
263:     const agentsDir = join(workspacePath, '.claude', 'agents');
264:     await Promise.all([
265:       mkdir(skillsDir, { recursive: true }),
266:       mkdir(agentsDir, { recursive: true }),
267:     ]);
268: 
269:     // --- Phase 1: Run all independent file generation + downloads in parallel ---
270:     const docGroups = scope.documentGroups ?? [];
271: 
272:     const createDocGroupSymlinks = async () => {
273:       if (docGroups.length === 0) return;
274:       const docsDir = join(workspacePath, 'documents');
275:       await mkdir(docsDir, { recursive: true });
276:       await Promise.all(docGroups.map(async (group) => {
277:         const linkName = group.name.replace(/[/\\:*?"<>|]/g, '-');
278:         const linkPath = join(docsDir, linkName);
279:         try {
280:           await symlink(group.storagePath, linkPath);
281:         } catch (err: any) {
282:           if (err.code !== 'EEXIST') {
283:             console.error(`Failed to symlink doc group "${group.name}":`, err.message);
284:           }
285:         }
286:       }));
287:     };
288: 
289:     const downloadAllSkills = async () => {
290:       await Promise.all(scope.skills.map(async (skill) => {
291:         try {
292:           await this.downloadSkill(skill, skillsDir);
293:         } catch (error) {
294:           console.error(`Failed to download skill "${skill.name}" for session ${sessionId}:`, error instanceof Error ? error.message : error);
295:         }
296:       }));
297:     };
298: 
299:     await Promise.all([
300:       this.generateScopeClaudeMd(workspacePath, scope, selectedAgentId, userId),
301:       this.writeScopeSystemPromptFile(workspacePath, scope),
302:       this.generateAgentSubagentFiles(agentsDir, scope.agents, skillsDir),
303:       this.generateSettings(workspacePath, scope.mcpServers, scope.settings),
304:       this.writeMemoryFiles(workspacePath, scope.id, userId),
305:       createDocGroupSymlinks(),
306:       downloadAllSkills(),
307:     ]);
308: 
309:     // --- Phase 2: Things that depend on phase 1 ---
310:     // Built-in skills must run after S3 downloads (won't overwrite existing)
311:     const builtinCopied = await this.copyBuiltinSkills(skillsDir);
312:     if (builtinCopied.length > 0) {
313:       console.log(`Loaded built-in skills for session ${sessionId}: ${builtinCopied.join(', ')}`);
314:     }
315: 
316:     // Generate RAG knowledge-search skill if enabled and scope has knowledge bases or document groups
317:     const { isRagEnabled } = await import('./rag/document-indexer.service.js');
318:     const { knowledgeBaseService } = await import('./knowledge-base.service.js');
319:     const kbIds = await knowledgeBaseService.getKnowledgeBaseIdsForScope(scope.id);
320:     const hasKnowledgeSources = docGroups.length > 0 || kbIds.length > 0;
321: 
322:     if (isRagEnabled() && hasKnowledgeSources) {
323:       const ragSkillPath = join(skillsDir, 'knowledge-search.md');
324:       const backendUrl = this.resolveBackendUrl();
325:       const ragSkillContent = this.buildRagSkillContent(backendUrl, {
326:         knowledgeBaseIds: kbIds.length > 0 ? kbIds : undefined,
327:         scopeId: kbIds.length === 0 ? scope.id : undefined,
328:       });
329:       if (ragSkillContent) {
330:         await writeFile(ragSkillPath, ragSkillContent, 'utf-8');
331:       }
332:     }
333: 
334:     // Install plugins (git clone) — also parallelized internally
335:     const pluginPaths = await this.installPlugins(workspacePath, scope.plugins ?? []);
336: 
337:     // Inject InsForge app backend MCP configs (if any apps in this scope have backends)
338:     try {
339:       const { agentAppDataResolver } = await import('./agent-app-data-resolver.js');
340:       const injected = await agentAppDataResolver.injectIntoWorkspace(workspacePath, orgId, scope.id);
341:       if (injected > 0) {
342:         console.log(`[workspace] Injected ${injected} InsForge app backend MCP config(s) for scope ${scope.id}`);
343:       }
344:     } catch (err) {
345:       console.warn('[workspace] Failed to inject InsForge MCP configs:', err instanceof Error ? err.message : err);
346:     }
347: 
348:     // Write manifest
349:     const now = new Date().toISOString();
350:     await this.writeManifest(workspacePath, {
351:       sessionId,
352:       businessScopeId: scope.id,
353:       configVersion: scope.configVersion,
354:       agentId: selectedAgentId,
355:       provisionedAt: now,
356:       lastSyncedAt: now,
357:       agents: scope.agents.map(a => ({ id: a.id, name: a.name })),
358:       skills: scope.skills.map(s => ({ id: s.id, name: s.name, hashId: s.hashId })),
359:     });
360: 
361:     return { workspacePath, pluginPaths };
362:   }
363: 
364:   // =========================================================================
365:   // Lazy refresh (config version check)
366:   // =========================================================================
