368:   /**
369:    * Check if the session workspace is up-to-date with the scope's config_version.
370:    * If stale, refresh the workspace files. Returns true if a refresh happened.
371:    */
372:   async ensureWorkspaceUpToDate(
373:     orgId: string,
374:     sessionId: string,
375:     scope: ScopeForWorkspace,
376:     selectedAgentId: string | null,
377:     userId?: string,
378:   ): Promise<{ refreshed: boolean; pluginPaths: string[] }> {
379:     const workspacePath = this.getSessionWorkspacePath(orgId, scope.id, sessionId);
380:     const manifest = await this.readManifest(workspacePath);
381: 
382:     if (!manifest) {
383:       // No manifest — full provision
384:       const result = await this.ensureSessionWorkspace(orgId, sessionId, scope, selectedAgentId, userId);
385:       return { refreshed: true, pluginPaths: result.pluginPaths };
386:     }
387: 
388:     if (manifest.configVersion >= scope.configVersion) {
389:       // Already up to date — still resolve plugin paths for the SDK
390:       const pluginPaths = await this.installPlugins(workspacePath, scope.plugins ?? []);
391:       return { refreshed: false, pluginPaths };
392:     }
393: 
394:     // Refresh
395:     await this.refreshSessionWorkspace(workspacePath, scope, selectedAgentId, manifest, userId);
396:     const pluginPaths = await this.installPlugins(workspacePath, scope.plugins ?? []);
397:     return { refreshed: true, pluginPaths };
398:   }
