400:   /**
401:    * Targeted refresh: regenerate CLAUDE.md, agents, diff skills, update manifest.
402:    */
403:   async refreshSessionWorkspace(
404:     workspacePath: string,
405:     scope: ScopeForWorkspace,
406:     selectedAgentId: string | null,
407:     manifest: WorkspaceManifest,
408:     userId?: string,
409:   ): Promise<void> {
410:     // 1. Regenerate CLAUDE.md
411:     await this.generateScopeClaudeMd(workspacePath, scope, selectedAgentId, userId);
412: 
413:     // 1a. Refresh scope system prompt file
414:     await this.writeScopeSystemPromptFile(workspacePath, scope);
415: 
416:     // 1b. Refresh memory files
417:     await this.writeMemoryFiles(workspacePath, scope.id, userId);
418: 
419:     // 2. Regenerate agent subagent files
420:     const agentsDir = join(workspacePath, '.claude', 'agents');
421:     await rm(agentsDir, { recursive: true, force: true });
422:     await mkdir(agentsDir, { recursive: true });
423:     await this.generateAgentSubagentFiles(agentsDir, scope.agents, join(workspacePath, '.claude', 'skills'));
424: 
425:     // 3. Diff and sync skills
426:     await this.syncSkills(workspacePath, manifest.skills, scope.skills);
427: 
428:     // 4. Regenerate settings
429:     await this.generateSettings(workspacePath, scope.mcpServers, scope.settings);
430: 
431:     // 5. Sync document group symlinks
432:     const docGroups = scope.documentGroups ?? [];
433:     const docsDir = join(workspacePath, 'documents');
434:     if (docGroups.length > 0) {
435:       await mkdir(docsDir, { recursive: true });
436: 
437:       // Remove stale symlinks for groups no longer assigned
438:       const desiredNames = new Set(docGroups.map(g => g.name.replace(/[/\\:*?"<>|]/g, '-')));
439:       try {
440:         const existing = await readdir(docsDir);
441:         for (const entry of existing) {
442:           if (!desiredNames.has(entry)) {
443:             await rm(join(docsDir, entry), { force: true }).catch(() => {});
444:           }
445:         }
446:       } catch { /* docsDir may not exist yet */ }
447: 
448:       // Create missing symlinks
449:       for (const group of docGroups) {
450:         const linkName = group.name.replace(/[/\\:*?"<>|]/g, '-');
451:         const linkPath = join(docsDir, linkName);
452:         try {
453:           await symlink(group.storagePath, linkPath);
454:         } catch (err: any) {
455:           if (err.code !== 'EEXIST') {
456:             console.error(`Failed to symlink doc group "${group.name}":`, err.message);
457:           }
458:         }
459:       }
460:     } else {
461:       // No document groups — remove the documents directory if it exists
462:       await rm(docsDir, { recursive: true, force: true }).catch(() => {});
463:     }
464: 
465:     // 6. Regenerate RAG knowledge-search skill if applicable
466:     const skillsDir = join(workspacePath, '.claude', 'skills');
467:     const ragSkillPath = join(skillsDir, 'knowledge-search.md');
468:     const { isRagEnabled } = await import('./rag/document-indexer.service.js');
469:     const { knowledgeBaseService } = await import('./knowledge-base.service.js');
470:     const kbIds = await knowledgeBaseService.getKnowledgeBaseIdsForScope(scope.id);
471:     const hasKnowledgeSources = docGroups.length > 0 || kbIds.length > 0;
472: 
473:     if (isRagEnabled() && hasKnowledgeSources) {
474:       const backendUrl = this.resolveBackendUrl();
475:       const ragSkillContent = this.buildRagSkillContent(backendUrl, {
476:         knowledgeBaseIds: kbIds.length > 0 ? kbIds : undefined,
477:         scopeId: kbIds.length === 0 ? scope.id : undefined,
478:       });
479:       if (ragSkillContent) {
480:         await writeFile(ragSkillPath, ragSkillContent, 'utf-8');
481:       }
482:     } else {
483:       // Remove stale RAG skill if no longer applicable
484:       await rm(ragSkillPath, { force: true }).catch(() => {});
485:     }
486: 
487:     // 7. Update manifest
488:     await this.writeManifest(workspacePath, {
489:       ...manifest,
490:       configVersion: scope.configVersion,
491:       lastSyncedAt: new Date().toISOString(),
492:       agents: scope.agents.map(a => ({ id: a.id, name: a.name })),
493:       skills: scope.skills.map(s => ({ id: s.id, name: s.name, hashId: s.hashId })),
494:     });
495:   }
