514:       `scopeName: ${scope.name}`,
515:       'title: Scope System Prompt',
516:       '---',
517:       '',
518:       body,
519:       '',
520:     ];
521:     await writeFile(join(dir, 'scope-system-prompt.md'), lines.join('\n'), 'utf-8');
