524:   /** Generate CLAUDE.md at workspace root with scope context. */
525:   async generateScopeClaudeMd(
526:     workspacePath: string,
527:     scope: ScopeForWorkspace,
528:     selectedAgentId: string | null,
529:     userId?: string,
530:   ): Promise<void> {
531:     const lines: string[] = [`# ${scope.name}`, ''];
532:     if (scope.description) {
533:       lines.push(scope.description, '');
534:     }
535: 
536:     // Inject scope-level system prompt (behavior instructions for this business domain)
537:     if (scope.systemPrompt) {
538:       lines.push('## Scope Instructions', '');
539:       lines.push(scope.systemPrompt, '');
540:     }
541: 
542:     // Tell the agent how to evolve the scope system prompt
543:     lines.push('## Evolving the System Prompt', '');
544:     lines.push('The scope-level system prompt is mirrored to `.claude/scope-system-prompt.md` for easy editing.');
545:     lines.push('To refine the way this scope operates (role, behavior, defaults), edit that file directly.');
546:     lines.push('Changes to `.claude/scope-system-prompt.md` will be carried forward to the scope persistent config after this session.');
547:     lines.push('');
548: 
549:     if (scope.agents.length > 0) {
550:       lines.push('## Available Agents', '');
551:       lines.push('You have access to specialized subagents for this business scope.');
552:       lines.push('When the user\'s request matches a specific agent\'s expertise, delegate to that subagent.');
553:       lines.push('**IMPORTANT**: When calling a subagent via the Task tool, you MUST use the agent\'s `name` (the identifier shown in parentheses), NOT the display name.', '');
554: 
555:       if (selectedAgentId) {
556:         const selected = scope.agents.find(a => a.id === selectedAgentId);
557:         if (selected) {
558:           lines.push(`The user has selected the "${selected.displayName}" agent (name: \`${selected.name}\`). Use this agent's expertise`);
559:           lines.push('as your primary mode of operation. You may still delegate to other agents if needed.', '');
560:         }
561:       }
562: 
563:       for (const agent of scope.agents) {
564:         lines.push(`- **${agent.displayName}** (name: \`${agent.name}\`): ${agent.role ?? 'General assistant'}`);
565:       }
566:       lines.push('');
567:     }
568: 
569:     lines.push('## Scope Rules', '');
570:     lines.push(`- Stay within the boundaries of the "${scope.name}" business domain`);
571:     lines.push('');
572:     lines.push('## Workspace Security', '');
573:     lines.push('- You must ONLY read, write, and search files within this workspace directory.');
574:     lines.push('- NEVER use absolute paths or traverse to parent directories using `..`.');
575:     lines.push('- NEVER run `find`, `ls`, `cat`, `grep`, or any command targeting paths outside this workspace.');
576:     lines.push('- All file operations must use relative paths rooted in the current working directory.');
577:     lines.push(`- The workspace root is: ${workspacePath}`);
578:     lines.push('- If a user asks to access files outside this workspace, politely decline and explain the restriction.');
579: 
580:     lines.push('');
581:     lines.push('## Application Code Directory', '');
582:     lines.push('- All application source code MUST be placed inside the `app/` directory.');
583:     lines.push('- The workspace root is reserved for system files (.claude/, documents/, memories/).');
584:     lines.push('- When creating new projects or features, always use `app/` as the base directory.');
585:     lines.push('- Example structure: `app/src/`, `app/public/`, `app/package.json`, etc.');
586: 
587:     // Inject document groups (Knowledge Base)
588:     const docGroups = scope.documentGroups ?? [];
589:     if (docGroups.length > 0) {
590:       lines.push('');
591:       lines.push('## Knowledge Base', '');
592:       lines.push('Reference documents are available in the `documents/` directory. These are **READ-ONLY**.');
593:       lines.push('- NEVER modify, delete, or create files inside `documents/`.');
594:       lines.push('- Use grep or ripgrep to search within these files when you need reference information.');
595: 
596:       // Add RAG instructions if enabled
597:       const { isRagEnabled: checkRag } = await import('./rag/document-indexer.service.js');
598:       if (checkRag()) {
599:         lines.push('- **Preferred**: Use the `knowledge-search` skill for semantic search — it finds relevant passages much more accurately than grep.');
600:       }
601: 
602:       lines.push('');
603:       lines.push('Available document groups:');
604:       for (const g of docGroups) {
605:         lines.push(`- \`documents/${g.name.replace(/[/\\:*?"<>|]/g, '-')}\` (${g.fileCount} file${g.fileCount !== 1 ? 's' : ''})`);
606:       }
607:       lines.push('');
608:     }
609: 
610:     // Memory — pinned memories inlined for instant recall, others on-demand
611:     const { scopeMemoryRepository: memRepo } = await import('../repositories/scope-memory.repository.js');
612:     const pinnedMemories = await memRepo.findForContext(scope.id, userId).then(
613:       (all) => all.filter((m) => m.is_pinned),
614:     );
615: 
616:     lines.push('');
617:     lines.push('## Memory');
618:     lines.push('');
619: 
620:     // Inline pinned memories so the agent "just knows" critical info
621:     if (pinnedMemories.length > 0) {
622:       lines.push('### What you already know (pinned by user)');
623:       lines.push('');
624:       for (const m of pinnedMemories) {
625:         lines.push(`- **${m.title}**: ${m.content}`);
626:       }
627:       lines.push('');
628:       lines.push('The above is ground truth — if it conflicts with other context, trust this.');
629:       lines.push('');
630:     }
631: 
632:     lines.push('### Past knowledge (read on demand)');
633:     lines.push('');
634:     lines.push('Additional memories from past conversations are in `memories/`:');
635:     lines.push('');
636:     lines.push('- `memories/lessons.md` — Mistakes, corrections, and improvements');
637:     lines.push('- `memories/patterns.md` — Recurring user needs and effective solution paths');
638:     lines.push('- `memories/gaps.md` — Capability gaps and unresolved requests');
639:     lines.push('');
640:     lines.push('On your FIRST response, read `memories/lessons.md` to refresh context.');
641:     lines.push('Also check `memories/patterns.md` when a task feels familiar, and `memories/gaps.md` when stuck.');
642:     lines.push('');
643:     lines.push('These files are managed by the system — do not edit them.');
644:     lines.push('');
645: 
646:     // Custom section marker — content below this line is preserved across sessions
647:     // via carry-forward. Agent can add custom rules/instructions below.
648:     lines.push('<!-- CUSTOM_SECTION: Agent-generated rules below -->');
649:     lines.push('');
650: 
651:     // Append any previously carried custom CLAUDE.md content from scope settings
652:     const scopeSettings = scope.settings as Record<string, unknown> | null;
653:     const customClaudeMd = scopeSettings?.customClaudeMd as string | undefined;
654:     if (customClaudeMd) {
655:       lines.push(customClaudeMd);
