662:   /**
663:    * Write scope memories as separate files in the workspace memories/ directory.
664:    * Agent reads these on-demand via Read/Grep tools instead of having them
665:    * inlined in CLAUDE.md (avoids context window bloat).
666:    *
667:    * File layout:
668:    *   memories/pinned.md   — User-pinned important knowledge (check first)
669:    *   memories/lessons.md  — Mistakes, corrections, improvements
670:    *   memories/patterns.md — Recurring needs and effective solutions
671:    *   memories/gaps.md     — Capability gaps and unresolved requests
672:    *
673:    * Visibility: loads scope-level memories + user's own private memories.
674:    */
675:   async writeMemoryFiles(workspacePath: string, scopeId: string, userId?: string): Promise<void> {
676:     const { scopeMemoryRepository } = await import('../repositories/scope-memory.repository.js');
677:     const memories = await scopeMemoryRepository.findForContext(scopeId, userId);
678:     if (memories.length === 0) return;
679: 
680:     const memoriesDir = join(workspacePath, 'memories');
681:     await mkdir(memoriesDir, { recursive: true });
682: 
683:     // Group memories by file target
684:     const pinned: typeof memories = [];
685:     const lessons: typeof memories = [];
686:     const patterns: typeof memories = [];
687:     const gaps: typeof memories = [];
688: 
689:     for (const m of memories) {
690:       if (m.is_pinned) {
691:         pinned.push(m);
692:       } else if (m.category === 'lesson') {
693:         lessons.push(m);
694:       } else if (m.category === 'pattern') {
695:         patterns.push(m);
696:       } else if (m.category === 'gap') {
697:         gaps.push(m);
698:       } else {
699:         // Uncategorized goes to lessons as a safe default
700:         lessons.push(m);
701:       }
702:     }
703: 
704:     const formatMemories = (items: typeof memories): string => {
705:       if (items.length === 0) return '*No entries yet.*\n';
706:       return items.map(m => {
707:         const autoLabel = m.tags.includes('auto-distilled') ? ' *(auto)* ' : ' ';
708:         const date = m.created_at instanceof Date
709:           ? m.created_at.toISOString().split('T')[0]
710:           : '';
711:         return `### ${date}: ${m.title}\n${autoLabel}\n${m.content}\n`;
712:       }).join('\n');
713:     };
714: 
715:     await writeFile(
716:       join(memoriesDir, 'pinned.md'),
717:       `# Pinned Knowledge\n\nImportant knowledge pinned by the user. Always check before complex work.\n\n${formatMemories(pinned)}`,
718:       'utf-8',
719:     );
720:     await writeFile(
721:       join(memoriesDir, 'lessons.md'),
722:       `# Lessons Learned\n\nMistakes, corrections, and improvements from past conversations.\n\n${formatMemories(lessons)}`,
723:       'utf-8',
724:     );
725:     await writeFile(
726:       join(memoriesDir, 'patterns.md'),
727:       `# Patterns\n\nRecurring user needs and effective solution paths.\n\n${formatMemories(patterns)}`,
728:       'utf-8',
729:     );
730:     await writeFile(
731:       join(memoriesDir, 'gaps.md'),
732:       `# Capability Gaps\n\nKnown limitations and unresolved requests.\n\n${formatMemories(gaps)}`,
733:       'utf-8',
734:     );
735:   }
