781:   /** Generate .claude/settings.json with permissions and optional MCP servers. */
782:   async generateSettings(workspacePath: string, mcpServers?: McpServerForWorkspace[], scopeSettings?: Record<string, unknown> | null): Promise<void> {
783:     const settings: Record<string, unknown> = {
784:       permissions: {
785:         allow: ['Read', 'Write', 'Edit', 'Bash', 'Grep', 'Glob', 'Skill', 'WebFetch'],
786:       },
787:     };
788: 
789:     const mcpConfig: Record<string, unknown> = {};
790: 
791:     // In agentcore mode, add built-in AgentCore tools (Browser + Code Interpreter)
792:     if (config.agentRuntime === 'agentcore') {
793:       const agentcoreRegion = config.agentcore.runtimeArn?.split(':')[3] || config.aws.region;
794:       mcpConfig['agentcore-tools'] = {
795:         type: 'stdio',
796:         command: 'uvx',
797:         args: ['awslabs.amazon-bedrock-agentcore-mcp-server@latest'],
798:         env: {
799:           AWS_REGION: agentcoreRegion,
800:           AWS_DEFAULT_REGION: agentcoreRegion,
801:           BROWSER_REGION: agentcoreRegion,
802:           AGENTCORE_BROWSER_REGION: agentcoreRegion,
803:           FASTMCP_LOG_LEVEL: 'ERROR',
804:         },
805:       };
806:     }
807: 
808:     // Write scope-level MCP servers so Claude Code discovers them via project settings
809:     if (mcpServers && mcpServers.length > 0) {
810:       for (const server of mcpServers) {
811:         // Prefer structured config if available
812:         if (server.config && typeof server.config === 'object') {
813:           const c = server.config as Record<string, unknown>;
814:           const type = (c.type as string) || 'stdio';
815:           if (type === 'sse' || type === 'http') {
816:             mcpConfig[server.name] = { type, url: c.url };
817:           } else {
818:             const entry: Record<string, unknown> = { type: 'stdio', command: c.command };
819:             if (Array.isArray(c.args)) entry.args = c.args;
820:             if (c.env && typeof c.env === 'object' && Object.keys(c.env as object).length > 0) entry.env = c.env;
821:             mcpConfig[server.name] = entry;
822:           }
823:           continue;
824:         }
825: 
826:         // Fallback: parse from hostAddress string
827:         const address = server.hostAddress?.trim();
828:         if (!address) continue;
829:         if (address.startsWith('http://') || address.startsWith('https://')) {
830:           mcpConfig[server.name] = { type: 'sse', url: address };
831:         } else {
832:           const parts = address.split(/\s+/);
833:           mcpConfig[server.name] = {
834:             type: 'stdio',
835:             command: parts[0],
836:             args: parts.length > 1 ? parts.slice(1) : undefined,
837:             ...(server.env && Object.keys(server.env).length > 0 ? { env: server.env } : {}),
838:           };
839:         }
840:       }
841:     }
842: 
843:     if (Object.keys(mcpConfig).length > 0) {
844:       settings.mcpServers = mcpConfig;
845:     }
846: 
847:     // Include hooks from scope settings (carried forward from previous sessions)
848:     if (scopeSettings?.hooks && typeof scopeSettings.hooks === 'object') {
849:       settings.hooks = scopeSettings.hooks;
850:     }
851: 
852:     const settingsDir = join(workspacePath, '.claude');
853:     await mkdir(settingsDir, { recursive: true });
854:     await writeFile(join(settingsDir, 'settings.json'), JSON.stringify(settings, null, 2), 'utf-8');
855:   }
