861:   /** Diff old vs new skills and only download changed/new ones. */
862:   async syncSkills(
863:     workspacePath: string,
864:     oldSkills: Array<{ id: string; name: string; hashId: string }>,
865:     newSkills: SkillForWorkspace[],
866:   ): Promise<void> {
867:     const oldMap = new Map(oldSkills.map(s => [s.id, s]));
868:     const newMap = new Map(newSkills.map(s => [s.id, s]));
869:     const skillsDir = join(workspacePath, '.claude', 'skills');
870: 
871:     // Remove deleted skills
872:     for (const [id, old] of oldMap) {
873:       if (!newMap.has(id)) {
874:         await rm(join(skillsDir, old.name), { recursive: true, force: true });
875:       }
876:     }
877: 
878:     // Add new or updated skills (hash changed)
879:     for (const [id, skill] of newMap) {
880:       const old = oldMap.get(id);
881:       if (!old || old.hashId !== skill.hashId) {
882:         try {
883:           await this.downloadSkill(skill, skillsDir);
884:         } catch (error) {
885:           console.error(`Failed to sync skill "${skill.name}":`, error instanceof Error ? error.message : error);
886:         }
887:       }
888:     }
889:   }
