912:         } catch {
913:           // Doesn't exist — copy it
914:         }
915:         await cp(join(BUILTIN_SKILLS_DIR, entry.name), targetDir, { recursive: true });
916:         copied.push(entry.name);
917:       }
918:     } catch (error) {
919:       console.warn('Could not load built-in skills:', error instanceof Error ? error.message : error);
