928:   /**
929:    * Install plugins by cloning their git repos into .claude/plugins/{name}/.
930:    * Returns absolute paths to each installed plugin directory (for SDK `plugins` option).
931:    */
932:   async installPlugins(workspacePath: string, plugins: PluginForWorkspace[]): Promise<string[]> {
933:     if (!plugins || plugins.length === 0) return [];
934:     const pluginsDir = join(workspacePath, '.claude', 'plugins');
935:     await mkdir(pluginsDir, { recursive: true });
936: 
937:     const results = await Promise.all(plugins.map(async (plugin) => {
938:       const targetDir = join(pluginsDir, plugin.name);
939:       try {
940:         // Skip if already cloned
941:         await access(targetDir);
942:         return targetDir;
943:       } catch { /* not yet cloned */ }
944: 
945:       try {
946:         const { execFile } = await import('child_process');
947:         const { promisify } = await import('util');
948:         const execFileAsync = promisify(execFile);
949:         await execFileAsync('git', [
950:           'clone', '--depth', '1', '--branch', plugin.ref,
951:           plugin.gitUrl, targetDir,
952:         ], { timeout: 60_000 });
953:         console.log(`[installPlugins] Cloned plugin "${plugin.name}" from ${plugin.gitUrl}@${plugin.ref}`);
954:         return targetDir;
955:       } catch (error) {
956:         console.error(`[installPlugins] Failed to clone plugin "${plugin.name}":`, error instanceof Error ? error.message : error);
957:         return null;
958:       }
959:     }));
960: 
961:     return results.filter((p): p is string => p !== null);
962:   }
