964:   // =========================================================================
965:   // S3 skill download (preserved from original)
966:   // =========================================================================
967: 
968:   async downloadSkill(skill: SkillForWorkspace, targetDir: string): Promise<boolean> {
969:     const skillDir = join(targetDir, skill.name);
970:     
971:     // Check for local path first (marketplace-installed skills)
972:     if (skill.localPath) {
973:       try {
974:         await access(skill.localPath);
975:         await mkdir(skillDir, { recursive: true });
976:         await cp(skill.localPath, skillDir, { recursive: true });
977:         console.log(`[downloadSkill] Copied local skill "${skill.name}" from ${skill.localPath}`);
978:         return true;
979:       } catch (error) {
980:         console.warn(`[downloadSkill] Local path not accessible for "${skill.name}": ${skill.localPath}, falling back to S3`);
981:       }
982:     }
983:     
984:     // Fall back to S3 download
985:     const s3Key = `${skill.s3Prefix}skill.zip`;
986:     try {
987:       const response = await this.s3Client.send(new GetObjectCommand({ Bucket: skill.s3Bucket, Key: s3Key }));
988:       if (!response.Body) {
989:         console.error(`Empty response body for skill "${skill.name}" from s3://${skill.s3Bucket}/${s3Key}`);
990:         // Fall through to inline body fallback
991:       } else {
992:         await mkdir(skillDir, { recursive: true });
993: 
994:         const zipPath = join(skillDir, 'skill.zip');
995:         const bodyStream = response.Body as Readable;
996:         const writeStream = createWriteStream(zipPath);
997:         await pipeline(bodyStream, writeStream);
998: 
999:         await this.extractSkillZip(zipPath, skillDir);
1000: 
1001:         try { await rm(zipPath, { force: true }); } catch { /* non-critical */ }
1002:         return true;
1003:       }
1004:     } catch (error) {
1005:       // S3 failed — fall through to inline body fallback
1006:       if (!skill.body && !skill.description) {
1007:         console.error(`S3 download failed for skill "${skill.name}" from s3://${skill.s3Bucket}/${s3Key}:`, error instanceof Error ? error.message : error);
1008:       }
1009:     }
1010: 
1011:     // Fallback: write inline body as SKILL.md (for scope-generator created skills)
1012:     if (skill.body) {
1013:       await mkdir(skillDir, { recursive: true });
1014:       const content = [
1015:         '---',
1016:         `name: ${skill.name}`,
1017:         ...(skill.description ? [`description: ${skill.description}`] : []),
1018:         '---',
1019:         '',
1020:         skill.body,
1021:       ].join('\n');
1022:       await writeFile(join(skillDir, 'SKILL.md'), content, 'utf-8');
1023:       console.log(`[downloadSkill] Wrote inline skill "${skill.name}" from metadata body`);
1024:       return true;
1025:     }
1026: 
1027:     // Last resort: write a minimal SKILL.md with just name and description
1028:     // so the skill is still visible in the workspace even without full content
1029:     if (skill.description) {
1030:       await mkdir(skillDir, { recursive: true });
1031:       const content = [
1032:         '---',
1033:         `name: ${skill.name}`,
1034:         `description: ${skill.description}`,
1035:         '---',
1036:         '',
1037:         `# ${skill.name}`,
1038:         '',
1039:         skill.description,
1040:       ].join('\n');
1041:       await writeFile(join(skillDir, 'SKILL.md'), content, 'utf-8');
1042:       console.log(`[downloadSkill] Wrote minimal skill "${skill.name}" from description`);
1043:       return true;
1044:     }
1045: 
1046:     return false;
1047:   }
1048: 
1049:   private async extractSkillZip(zipPath: string, targetDir: string): Promise<void> {
1050:     const { execFile } = await import('child_process');
1051:     const { promisify } = await import('util');
1052:     const execFileAsync = promisify(execFile);
1053:     try {
1054:       await execFileAsync('unzip', ['-o', zipPath, '-d', targetDir]);
1055:     } catch {
1056:       try {
1057:         await execFileAsync('python3', ['-m', 'zipfile', '-e', zipPath, targetDir]);
1058:       } catch {
1059:         console.warn(`Could not extract ${zipPath}: no unzip utility available`);
1060:         throw new Error('Failed to extract skill archive: no extraction utility available');
1061:       }
1062:     }
1063:   }
