1092:   private async canReuseAgentWorkspace(agentId: string, skills: SkillForWorkspace[]): Promise<boolean> {
1093:     try {
1094:       const manifestPath = join(this.getWorkspacePath(agentId), MANIFEST_FILENAME);
1095:       await access(manifestPath);
1096:       const content = await readFile(manifestPath, 'utf-8');
1097:       const manifest = JSON.parse(content) as { agentId: string; skills: Array<{ id: string; hashId: string }> };
1098:       if (!manifest) return false;
1099: 
1100:       const currentSet = skills.map(s => `${s.id}:${s.hashId}`).sort().join(',');
1101:       const manifestSet = manifest.skills.map((s: { id: string; hashId: string }) => `${s.id}:${s.hashId}`).sort().join(',');
1102:       
1103:       if (currentSet !== manifestSet) return false;
1104:       
1105:       // Also verify skills actually exist on disk
1106:       const skillsDir = join(this.getWorkspacePath(agentId), '.claude', 'skills');
1107:       for (const skill of skills) {
1108:         const skillDir = join(skillsDir, skill.name);
1109:         try {
1110:           await access(skillDir);
1111:         } catch {
1112:           console.log(`[canReuseAgentWorkspace] Skill "${skill.name}" not found on disk, will re-provision`);
1113:           return false;
1114:         }
1115:       }
1116:       
1117:       return true;
1118:     } catch {
1119:       return false;
1120:     }
1121:   }
