1161:   /**
1162:    * Ensure the local workspace is up-to-date with S3 (agentcore mode).
1163:    * Downloads all files from S3 to the local workspace directory.
1164:    * This is needed before operations that require local filesystem access
1165:    * (e.g. dev server preview, app detection) because the agentcore container
1166:    * writes files to S3 and the sync-back to local is fire-and-forget.
1167:    *
1168:    * Returns the number of files downloaded.
1169:    */
1170:   async ensureS3SyncedToLocal(
1171:     orgId: string,
1172:     scopeId: string,
1173:     sessionId: string,
1174:   ): Promise<number> {
1175:     const s3Bucket = config.agentcore.workspaceS3Bucket;
1176:     const prefix = `${orgId}/${scopeId}/${sessionId}/`;
1177:     const localDir = this.getSessionWorkspacePath(orgId, scopeId, sessionId);
1178: 
1179:     let downloaded = 0;
1180:     let continuationToken: string | undefined;
1181: 
1182:     do {
1183:       const result = await this.s3Client.send(new ListObjectsV2Command({
1184:         Bucket: s3Bucket,
1185:         Prefix: prefix,
1186:         ContinuationToken: continuationToken,
1187:       }));
1188: 
1189:       for (const obj of result.Contents ?? []) {
1190:         if (!obj.Key) continue;
