1302:   private buildTreeFromKeys(keys: Array<{ key: string; size: number }>): WorkspaceFileNode[] {
1303:     const root: Map<string, any> = new Map();
1304: 
1305:     for (const { key, size } of keys) {
1306:       const parts = key.split('/');
1307:       let current = root;
1308:       for (let i = 0; i < parts.length; i++) {
1309:         const part = parts[i]!;
1310:         if (i === parts.length - 1) {
1311:           // File
1312:           current.set(part, { type: 'file', size });
1313:         } else {
1314:           // Directory
1315:           if (!current.has(part)) {
1316:             current.set(part, new Map());
1317:           }
1318:           current = current.get(part);
1319:         }
1320:       }
1321:     }
1322: 
1323:     const mapToNodes = (map: Map<string, any>, parentPath: string): WorkspaceFileNode[] => {
1324:       const nodes: WorkspaceFileNode[] = [];
1325:       const entries = [...map.entries()].sort(([aName, aVal], [bName, bVal]) => {
1326:         const aIsDir = aVal instanceof Map;
1327:         const bIsDir = bVal instanceof Map;
1328:         if (aIsDir && !bIsDir) return -1;
1329:         if (!aIsDir && bIsDir) return 1;
1330:         return aName.localeCompare(bName);
1331:       });
1332: 
1333:       for (const [name, value] of entries) {
1334:         const path = parentPath ? `${parentPath}/${name}` : name;
1335:         if (value instanceof Map) {
1336:           nodes.push({ name, path, type: 'directory', children: mapToNodes(value, path) });
1337:         } else {
1338:           nodes.push({ name, path, type: 'file', size: value.size });
1339:         }
1340:       }
1341:       return nodes;
1342:     };
1343: 
1344:     return mapToNodes(root, '');
1345:   }
