1647:   private async readDirRecursive(dir: string, rootDir: string): Promise<WorkspaceFileNode[]> {
1648:     const entries = await readdir(dir, { withFileTypes: true });
1649:     const nodes: WorkspaceFileNode[] = [];
1650: 
1651:     // Resolve whether each entry is a directory, following symlinks
1652:     const resolvedEntries: Array<{ entry: import('fs').Dirent; isDir: boolean }> = [];
1653:     for (const entry of entries) {
1654:       let isDir = entry.isDirectory();
1655:       if (entry.isSymbolicLink()) {
1656:         try {
1657:           const targetStat = await stat(join(dir, entry.name)); // stat follows symlinks
1658:           isDir = targetStat.isDirectory();
1659:         } catch {
1660:           // Broken symlink — treat as file
1661:           isDir = false;
1662:         }
1663:       }
1664:       resolvedEntries.push({ entry, isDir });
1665:     }
1666: 
1667:     resolvedEntries.sort((a, b) => {
1668:       // Directories first, then alphabetical
1669:       if (a.isDir && !b.isDir) return -1;
1670:       if (!a.isDir && b.isDir) return 1;
1671:       return a.entry.name.localeCompare(b.entry.name);
1672:     });
1673: 
1674:     for (const { entry, isDir } of resolvedEntries) {
1675:       const fullPath = join(dir, entry.name);
1676:       const relativePath = relative(rootDir, fullPath);
1677:       if (isDir) {
1678:         if (WorkspaceManager.SHALLOW_DIRS.has(entry.name)) {
1679:           nodes.push({ name: entry.name, path: relativePath, type: 'directory', children: [] });
1680:         } else {
1681:           try {
1682:             const children = await this.readDirRecursive(fullPath, rootDir);
1683:             nodes.push({ name: entry.name, path: relativePath, type: 'directory', children });
1684:           } catch {
1685:             // Directory may have been removed or is a broken symlink — show as empty
1686:             nodes.push({ name: entry.name, path: relativePath, type: 'directory', children: [] });
1687:           }
1688:         }
1689:       } else {
1690:         try {
1691:           const fileStat = await stat(fullPath);
1692:           nodes.push({ name: entry.name, path: relativePath, type: 'file', size: fileStat.size });
1693:         } catch {
1694:           // File may have been removed or is a broken symlink — show with size 0
1695:           nodes.push({ name: entry.name, path: relativePath, type: 'file', size: 0 });
1696:         }
1697:       }
1698:     }
1699:     return nodes;
1700:   }
