1702:   /**
1703:    * Remove session workspace directories whose manifests are older than maxAgeMs.
1704:    * Returns the number of directories removed.
1705:    */
1706:   async pruneStaleWorkspaces(maxAgeMs: number = 10 * 365 * 24 * 60 * 60 * 1000): Promise<number> {
1707:     let removed = 0;
1708:     const now = Date.now();
1709:     try {
1710:       const orgs = await readdir(this.baseDir, { withFileTypes: true });
1711:       for (const org of orgs) {
1712:         if (!org.isDirectory()) continue;
1713:         const orgDir = join(this.baseDir, org.name);
1714:         const scopes = await readdir(orgDir, { withFileTypes: true }).catch(() => []);
1715:         for (const scope of scopes) {
1716:           if (!scope.isDirectory()) continue;
1717:           const sessionsDir = join(orgDir, scope.name, 'sessions');
1718:           const sessions = await readdir(sessionsDir, { withFileTypes: true }).catch(() => []);
1719:           for (const sess of sessions) {
1720:             if (!sess.isDirectory()) continue;
1721:             const wsPath = join(sessionsDir, sess.name);
1722:             const manifest = await this.readManifest(wsPath);
1723:             const lastSync = manifest?.lastSyncedAt ? new Date(manifest.lastSyncedAt).getTime() : 0;
1724:             if (now - lastSync > maxAgeMs) {
1725:               await rm(wsPath, { recursive: true, force: true }).catch(() => {});
1726:               removed++;
1727:             }
1728:           }
1729:         }
1730:       }
1731:     } catch {
1732:       // baseDir may not exist yet
1733:     }
1734:     return removed;
1735:   }
1736: }
