34: /**
35:  * Provision a workspace for workflow execution.
36:  *
37:  * Loads scope data, agents with their skills, scope-level skills,
38:  * and creates a session workspace with all resources available.
39:  *
40:  * @param organizationId - Organization ID
41:  * @param scopeId - Business scope ID
42:  * @param sessionId - Optional session ID for workspace. If provided, the workspace
43:  *   can be retrieved later (e.g. using executionId). Defaults to a random UUID.
44:  */
45: export async function provisionWorkflowWorkspace(
46:   organizationId: string,
47:   scopeId: string,
48:   sessionId?: string,
49: ): Promise<WorkflowWorkspaceResult> {
50:   // Load scope
51:   const scope = await businessScopeService.getBusinessScopeById(scopeId, organizationId);
52:   if (!scope) throw new Error('Business scope not found');
53: 
54:   // Load agents with skills
55:   const agents = await agentRepository.findByBusinessScope(organizationId, scopeId);
56:   const agentSkillsMap = new Map<string, string[]>();
57:   for (const agent of agents) {
58:     const agentSkills = await skillRepository.findByAgentId(organizationId, agent.id);
59:     agentSkillsMap.set(agent.id, agentSkills.map(s => s.name));
60:   }
61: 
62:   // Load scope-level skills
63:   const scopeLevelSkills = await skillService.getScopeLevelSkills(organizationId, scopeId);
64: 
65:   // Build combined skills list
66:   const skillMap = new Map<string, SkillForWorkspace>();
67:   for (const agent of agents) {
68:     const agentSkills = await skillRepository.findByAgentId(organizationId, agent.id);
69:     for (const s of agentSkills) {
70:       if (!skillMap.has(s.id)) {
71:         const meta = s.metadata as Record<string, unknown> | null;
72:         skillMap.set(s.id, {
73:           id: s.id, name: s.name, hashId: s.hash_id,
74:           s3Bucket: s.s3_bucket, s3Prefix: s.s3_prefix,
75:           localPath: meta?.localPath as string | undefined,
76:         });
77:       }
78:     }
79:   }
80:   for (const s of scopeLevelSkills) {
81:     if (!skillMap.has(s.id)) {
82:       const meta = s.metadata as Record<string, unknown> | null;
83:       skillMap.set(s.id, {
84:         id: s.id, name: s.name, hashId: s.hash_id,
85:         s3Bucket: s.s3_bucket, s3Prefix: s.s3_prefix,
86:         localPath: meta?.localPath as string | undefined,
87:       });
88:     }
89:   }
90: 
91:   // Provision workspace — use provided sessionId or generate a random one
92:   const effectiveSessionId = sessionId ?? crypto.randomUUID();
93:   const scopeForWorkspace: ScopeForWorkspace = {
94:     id: scope.id,
95:     name: scope.name,
96:     description: scope.description,
97:     systemPrompt: scope.system_prompt ?? null,
98:     configVersion: scope.config_version ?? 1,
99:     agents: agents.map(a => ({
100:       id: a.id,
101:       name: a.name,
102:       displayName: a.display_name,
103:       role: a.role,
104:       systemPrompt: a.system_prompt,
105:       skillNames: agentSkillsMap.get(a.id) || [],
106:     })),
107:     skills: Array.from(skillMap.values()),
108:     mcpServers: [],
109:     plugins: [],
110:   };
111: 
112:   const { workspacePath } = await workspaceManager.ensureSessionWorkspace(
113:     organizationId, effectiveSessionId, scopeForWorkspace, null,
114:   );
115: 
116:   return {
117:     workspacePath,
118:     sessionId: effectiveSessionId,
119:     scopeId: scope.id,
120:     agents: agents.map(a => ({ id: a.id, name: a.name, displayName: a.display_name, role: a.role })),
121:     skills: Array.from(skillMap.values()),
122:     scopeSkillNames: scopeLevelSkills.map(s => s.name),
123:   };
