127: // ---------------------------------------------------------------------------
128: // Workspace Snapshot — S3 backup/restore for checkpoint pause/resume
129: // ---------------------------------------------------------------------------
130: 
131: const S3_REGION = process.env.WORKSPACE_S3_REGION ?? 'ap-northeast-1';
132: const WORKSPACE_S3_BUCKET = process.env.WORKSPACE_S3_BUCKET ?? config?.agentcore?.workspaceS3Bucket ?? '';
133: 
134: const s3 = new S3Client({ region: S3_REGION });
135: 
136: /** Directories to skip during snapshot (large, auto-generated) */
137: const SKIP_DIRS = new Set([
138:   'node_modules', '.git', '__pycache__',
139:   '.venv', 'venv', 'env', '.env',
140:   '.tox', '.mypy_cache', '.pytest_cache', '.ruff_cache',
141:   '.next', '.nuxt', '.turbo', '.cache', '.parcel-cache',
142:   'bower_components', '.gradle', 'target', '.cargo',
143: ]);
144: 
145: const MAX_FILE_SIZE = 100 * 1024 * 1024; // 100MB
146: 
147: /**
148:  * Snapshot the current workspace to S3 for later restoration.
149:  * Called when a workflow pauses at a checkpoint node.
150:  *
151:  * S3 layout: s3://{bucket}/workflow-snapshots/{executionId}/{relativePath}
152:  *
153:  * @returns Number of files uploaded
154:  */
155: export async function snapshotWorkspaceToS3(
156:   workspacePath: string,
157:   executionId: string,
158: ): Promise<number> {
159:   if (!WORKSPACE_S3_BUCKET) {
160:     console.warn('[workflow-workspace] No S3 bucket configured, skipping snapshot');
161:     return 0;
162:   }
163: 
164:   const prefix = `workflow-snapshots/${executionId}/`;
165:   let uploaded = 0;
166: 
167:   const files = walkDir(workspacePath);
168:   console.log(`[workflow-workspace] Snapshotting ${files.length} files to s3://${WORKSPACE_S3_BUCKET}/${prefix}`);
169: 
170:   // Upload in parallel batches (concurrency = 10)
171:   const CONCURRENCY = 10;
172:   for (let i = 0; i < files.length; i += CONCURRENCY) {
173:     const batch = files.slice(i, i + CONCURRENCY);
174:     const results = await Promise.allSettled(batch.map(async (filePath) => {
175:       const relativePath = relative(workspacePath, filePath);
176:       const key = `${prefix}${relativePath}`;
177:       const fileStat = statSync(filePath);
178:       await s3.send(new PutObjectCommand({
179:         Bucket: WORKSPACE_S3_BUCKET,
180:         Key: key,
181:         Body: createReadStream(filePath),
182:         ContentLength: fileStat.size,
183:       }));
184:     }));
185:     for (const r of results) {
186:       if (r.status === 'fulfilled') uploaded++;
187:     }
188:   }
189: 
190:   console.log(`[workflow-workspace] Snapshot complete: ${uploaded} files → s3://${WORKSPACE_S3_BUCKET}/${prefix}`);
191:   return uploaded;
192: }
193: 
194: /**
195:  * Restore a workspace snapshot from S3.
196:  * Called when a workflow resumes after a checkpoint is resolved.
197:  *
198:  * Downloads all files from s3://{bucket}/workflow-snapshots/{executionId}/
199:  * into the provided workspacePath, preserving directory structure.
200:  *
201:  * @returns Number of files restored
202:  */
203: export async function restoreWorkspaceFromSnapshot(
204:   workspacePath: string,
205:   executionId: string,
206: ): Promise<number> {
207:   if (!WORKSPACE_S3_BUCKET) {
208:     console.warn('[workflow-workspace] No S3 bucket configured, skipping restore');
209:     return 0;
210:   }
211: 
212:   const prefix = `workflow-snapshots/${executionId}/`;
213: 
214:   // List all objects under the snapshot prefix
215:   const allKeys: string[] = [];
216:   let continuationToken: string | undefined;
217:   do {
218:     const result = await s3.send(new ListObjectsV2Command({
219:       Bucket: WORKSPACE_S3_BUCKET,
220:       Prefix: prefix,
221:       ContinuationToken: continuationToken,
222:     }));
223:     for (const obj of result.Contents ?? []) {
224:       if (obj.Key) allKeys.push(obj.Key);
225:     }
226:     continuationToken = result.NextContinuationToken;
227:   } while (continuationToken);
228: 
229:   if (allKeys.length === 0) {
230:     console.log(`[workflow-workspace] No snapshot found at s3://${WORKSPACE_S3_BUCKET}/${prefix}`);
231:     return 0;
232:   }
233: 
234:   console.log(`[workflow-workspace] Restoring ${allKeys.length} files from snapshot...`);
235: 
236:   let restored = 0;
237:   // Download in parallel batches
238:   const CONCURRENCY = 10;
239:   for (let i = 0; i < allKeys.length; i += CONCURRENCY) {
240:     const batch = allKeys.slice(i, i + CONCURRENCY);
241:     const results = await Promise.allSettled(batch.map(async (key) => {
242:       const relativePath = key.slice(prefix.length);
243:       if (!relativePath || relativePath.endsWith('/')) return;
244: 
245:       const localPath = join(workspacePath, relativePath);
246:       mkdirSync(join(localPath, '..'), { recursive: true });
247: 
248:       const response = await s3.send(new GetObjectCommand({
249:         Bucket: WORKSPACE_S3_BUCKET,
250:         Key: key,
251:       }));
252:       if (response.Body) {
253:         await pipeline(response.Body as NodeJS.ReadableStream, createWriteStream(localPath));
254:       }
255:     }));
256:     for (const r of results) {
257:       if (r.status === 'fulfilled') restored++;
258:     }
259:   }
260: 
261:   console.log(`[workflow-workspace] Restored ${restored}/${allKeys.length} files from snapshot`);
262:   return restored;
263: }
264: 
265: // ---------------------------------------------------------------------------
266: // Helpers
267: // ---------------------------------------------------------------------------
268: 
269: function walkDir(dir: string): string[] {
270:   const results: string[] = [];
271:   if (!existsSync(dir)) return results;
272: 
273:   for (const entry of readdirSync(dir, { withFileTypes: true })) {
274:     if (SKIP_DIRS.has(entry.name)) continue;
275:     const fullPath = join(dir, entry.name);
276:     if (entry.isDirectory()) {
277:       results.push(...walkDir(fullPath));
278:     } else {
279:       try {
280:         const stat = statSync(fullPath);
281:         if (stat.size <= MAX_FILE_SIZE) {
282:           results.push(fullPath);
283:         }
284:       } catch { /* skip unreadable files */ }
285:     }
286:   }
287:   return results;
288: }

