1: /**
2:  * Workspace Sync — mirrors /workspace ↔ S3.
3:  *
4:  * The backend uploads the full workspace (skills, agents, CLAUDE.md, etc.)
5:  * to S3 before invoking AgentCore. This module:
6:  *   - restoreWorkspaceFromS3: downloads S3 → /workspace/
7:  *   - syncWorkspaceToS3: uploads /workspace/ → S3
8:  *
9:  * S3 layout mirrors the local workspace exactly:
10:  *   s3://{bucket}/{prefix}.claude/skills/...
11:  *   s3://{bucket}/{prefix}.claude/agents/...
12:  *   s3://{bucket}/{prefix}.claude/CLAUDE.md
13:  *   s3://{bucket}/{prefix}.claude/settings.json
14:  *   s3://{bucket}/{prefix}README.md  (agent-generated files)
15:  */
16: 
17: import {
18:   S3Client,
19:   PutObjectCommand,
20:   GetObjectCommand,
21:   ListObjectsV2Command,
22: } from '@aws-sdk/client-s3';
23: import fs from 'fs';
24: import path from 'path';
25: import { pipeline } from 'stream/promises';
26: import { createReadStream, createWriteStream } from 'fs';
27: 
28: const WORKSPACE_DIR = '/workspace';
29: /**
30:  * Directories to skip during S3 sync.
31:  * These are large, auto-generated directories that can be recreated locally
32:  * and would massively slow down sync (node_modules alone can be 100k+ files).
33:  */
34: const SKIP_DIRS = new Set([
35:   'node_modules',
36:   '.git',
37:   '__pycache__',
38:   '.venv',
39:   'venv',
40:   'env',
41:   '.env',
42:   '.tox',
43:   '.mypy_cache',
44:   '.pytest_cache',
45:   '.ruff_cache',
46:   '.next',
47:   '.nuxt',
48:   '.turbo',
49:   '.cache',
50:   '.parcel-cache',
51:   'bower_components',
52:   '.gradle',
53:   'target',          // Maven/Rust
54:   '.cargo',
55: ]);
56: const MAX_FILE_SIZE = 100 * 1024 * 1024;
57: 
58: // ---------------------------------------------------------------------------
59: // Restore: S3 → /workspace/
60: // ---------------------------------------------------------------------------
61: 
62: export async function restoreWorkspaceFromS3(
63:   s3: S3Client,
64:   bucket: string,
65:   prefix: string,
66: ): Promise<number> {
67:   // List all objects under the prefix
68:   const allKeys: string[] = [];
69:   let continuationToken: string | undefined;
70:   do {
71:     const result = await s3.send(new ListObjectsV2Command({
72:       Bucket: bucket,
73:       Prefix: prefix,
74:       ContinuationToken: continuationToken,
75:     }));
76:     for (const obj of result.Contents ?? []) {
77:       if (obj.Key) allKeys.push(obj.Key);
78:     }
79:     continuationToken = result.NextContinuationToken;
80:   } while (continuationToken);
81: 
82:   if (allKeys.length === 0) {
83:     console.log(`[workspace-sync] No files found at s3://${bucket}/${prefix}`);
84:     return 0;
85:   }
86: 
87:   console.log(`[workspace-sync] Restoring ${allKeys.length} files from S3...`);
88: 
89:   let restored = 0;
90:   for (const key of allKeys) {
91:     const relativePath = key.slice(prefix.length);
92:     if (!relativePath) continue;
93: 
94:     const localPath = path.join(WORKSPACE_DIR, relativePath);
95:     fs.mkdirSync(path.dirname(localPath), { recursive: true });
96: 
97:     try {
98:       const response = await s3.send(new GetObjectCommand({ Bucket: bucket, Key: key }));
99:       if (response.Body) {
100:         await pipeline(response.Body as NodeJS.ReadableStream, createWriteStream(localPath));
101:         restored++;
102:       }
103:     } catch (err) {
104:       console.warn(`[workspace-sync] Failed to restore ${relativePath}: ${err}`);
105:     }
106:   }
107: 
108:   console.log(`[workspace-sync] Restored ${restored}/${allKeys.length} files`);
109:   return restored;
110: }
111: 
112: // ---------------------------------------------------------------------------
113: // Sync: /workspace/ → S3
114: // ---------------------------------------------------------------------------
115: 
116: export async function syncWorkspaceToS3(
117:   s3: S3Client,
118:   bucket: string,
119:   prefix: string,
120: ): Promise<number> {
121:   let uploaded = 0;
122: 
123:   for (const filePath of walkDir(WORKSPACE_DIR)) {
124:     const relativePath = path.relative(WORKSPACE_DIR, filePath);
125:     const key = `${prefix}${relativePath}`;
126: 
127:     try {
128:       const fileStat = fs.statSync(filePath);
129:       if (fileStat.size > MAX_FILE_SIZE) continue;
130: 
131:       await s3.send(new PutObjectCommand({
132:         Bucket: bucket,
133:         Key: key,
134:         Body: createReadStream(filePath),
135:         ContentLength: fileStat.size,
136:       }));
137:       uploaded++;
138:     } catch (err) {
139:       console.warn(`[workspace-sync] Upload failed for ${key}: ${err}`);
140:     }
141:   }
142: 
143:   if (uploaded > 0) {
144:     console.log(`[workspace-sync] Synced ${uploaded} files to s3://${bucket}/${prefix}`);
145:   }
146:   return uploaded;
147: }
148: 
149: // ---------------------------------------------------------------------------
150: // Helpers
151: // ---------------------------------------------------------------------------
152: 
153: function walkDir(dir: string): string[] {
154:   const results: string[] = [];
155:   if (!fs.existsSync(dir)) return results;
156: 
157:   for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
158:     if (SKIP_DIRS.has(entry.name)) continue;
159:     const fullPath = path.join(dir, entry.name);
160:     if (entry.isDirectory()) {
161:       results.push(...walkDir(fullPath));
162:     } else {
163:       results.push(fullPath);
164:     }
165:   }
166:   return results;
167: }

