38: class WebhookService {
39:   /**
40:    * Generate a unique webhook ID
41:    */
42:   private generateWebhookId(): string {
43:     const randomBytes = crypto.randomBytes(WEBHOOK_ID_LENGTH / 2);
44:     return `${WEBHOOK_ID_PREFIX}${randomBytes.toString('hex')}`;
45:   }
46: 
47:   /**
48:    * Generate a webhook secret
49:    */
50:   private generateSecret(): { secret: string; hash: string } {
51:     const secret = crypto.randomBytes(32).toString('hex');
52:     const hash = crypto.createHash('sha256').update(secret).digest('hex');
53:     return { secret, hash };
54:   }
