56:   /**
57:    * Create a webhook for a workflow
58:    */
59:   async createWebhook(
60:     organizationId: string,
61:     workflowId: string,
62:     options: {
63:       name?: string;
64:       timeoutSeconds?: number;
65:       generateSecret?: boolean;
66:       allowedIps?: string[];
67:       createdBy?: string;
68:     } = {}
69:   ): Promise<{ webhook: WebhookConfig; secret?: string; webhookUrl: string }> {
70:     // Verify workflow exists
71:     const workflow = await workflowRepository.findById(workflowId, organizationId);
72:     if (!workflow) {
73:       throw new Error('Workflow not found');
74:     }
75: 
76:     const webhookId = this.generateWebhookId();
77:     let secretHash: string | null = null;
78:     let secret: string | undefined;
79: 
80:     if (options.generateSecret) {
81:       const generated = this.generateSecret();
82:       secret = generated.secret;
83:       secretHash = generated.hash;
84:     }
85: 
86:     const webhook = await prisma.webhooks.create({
87:       data: {
88:         organization_id: organizationId,
89:         workflow_id: workflowId,
90:         webhook_id: webhookId,
91:         name: options.name,
92:         timeout_seconds: options.timeoutSeconds || 30,
93:         secret_hash: secretHash,
94:         allowed_ips: options.allowedIps || [],
95:         created_by: options.createdBy,
96:       },
97:     });
98: 
99:     const config = this.mapToWebhookConfig(webhook);
100:     const webhookUrl = this.generateWebhookUrl(webhookId);
101: 
102:     return { webhook: config, secret, webhookUrl };
103:   }
