105:   /**
106:    * Get webhook configuration by webhook ID
107:    */
108:   async getWebhookConfig(webhookId: string): Promise<WebhookConfig | null> {
109:     // Check cache first
110:     const cacheKey = `webhook:${webhookId}`;
111:     const cached = await redisService.get(cacheKey);
112:     if (cached) {
113:       return JSON.parse(cached);
114:     }
115: 
116:     const webhook = await prisma.webhooks.findFirst({
117:       where: { webhook_id: webhookId, deleted_at: null },
118:     });
119: 
120:     if (!webhook) {
121:       return null;
122:     }
123: 
124:     const config = this.mapToWebhookConfig(webhook);
125: 
126:     // Cache for 5 minutes (TTL in ms)
127:     await redisService.set(cacheKey, JSON.stringify(config), WEBHOOK_CONFIG_CACHE_TTL * 1000);
128: 
129:     return config;
130:   }
