132:   /**
133:    * Trigger a webhook (fire-and-forget execution)
134:    */
135:   async triggerWebhook(
136:     webhookId: string,
137:     payload: {
138:       variables?: Record<string, unknown>;
139:       headers?: Record<string, string>;
140:       ipAddress?: string;
141:     }
142:   ): Promise<{ received: boolean; callRecordId: string }> {
143:     const startTime = Date.now();
144:     const config = await this.getWebhookConfig(webhookId);
145: 
146:     if (!config) {
147:       throw new Error('Webhook not found');
148:     }
149: 
150:     if (!config.isEnabled) {
151:       throw new Error('Webhook is disabled');
152:     }
153: 
154:     // Check IP allowlist if configured
155:     if (config.allowedIps.length > 0 && payload.ipAddress) {
156:       if (!config.allowedIps.includes(payload.ipAddress)) {
157:         throw new Error('IP address not allowed');
158:       }
159:     }
160: 
161:     // Create call record
162:     const callRecord = await prisma.webhook_call_records.create({
163:       data: {
164:         webhook_id: webhookId,
165:         organization_id: config.organizationId,
166:         request_method: 'POST',
167:         request_headers: payload.headers || {},
168:         request_body: payload.variables || {},
169:         status: 'pending',
170:         ip_address: payload.ipAddress,
171:       },
172:     });
173: 
174:     // Fire-and-forget execution
175:     this.executeWebhookAsync(config, payload.variables || {}, callRecord.id, startTime)
176:       .catch(error => {
177:         console.error(`[WEBHOOK_ERROR] webhookId=${webhookId} error=${error.message}`);
178:       });
179: 
180:     return { received: true, callRecordId: callRecord.id };
181:   }
