183:   /**
184:    * Execute webhook asynchronously
185:    */
186:   private async executeWebhookAsync(
187:     config: WebhookConfig,
188:     variables: Record<string, unknown>,
189:     callRecordId: string,
190:     startTime: number
191:   ): Promise<void> {
192:     try {
193:       const workflow = await workflowRepository.findById(config.workflowId, config.organizationId);
194:       if (!workflow) {
195:         throw new Error('Workflow not found');
196:       }
197: 
198:       const scopeId = (workflow as any).business_scope_id;
199:       if (!scopeId) {
200:         throw new Error('Workflow has no business scope assigned');
201:       }
202: 
203:       // Build V2 plan from stored workflow (same as schedule/manual Run)
204:       const webhookVariables = Object.entries(variables).map(([name, value]) => ({
205:         variableId: `var-${name}`,
206:         name,
207:         value: String(value),
208:         description: '',
209:       }));
210: 
211:       const nodes = (workflow.nodes || []) as Array<{
212:         id: string; title?: string; label?: string; type: string; prompt?: string;
213:         dependentTasks?: string[]; agentId?: string;
214:         metadata?: Record<string, unknown>;
215:       }>;
216: 
217:       const plan: WorkflowV2Plan = {
218:         title: workflow.name,
219:         nodes: nodes.map(n => ({
220:           id: n.id,
221:           title: n.title || n.label || n.id,
222:           type: (n.type as 'agent' | 'action' | 'condition' | 'document' | 'codeArtifact') || 'agent',
223:           prompt: n.prompt || (n.metadata?.prompt as string) || n.title || n.label || n.id,
224:           dependentTasks: n.dependentTasks || (n.metadata?.dependentTasks as string[]),
225:           agentId: n.agentId || (n.metadata?.agentId as string),
226:         })),
227:         edges: ((workflow.connections || []) as Array<{ source?: string; target?: string; from?: string; to?: string }>).map(c => ({
228:           source: c.source || c.from || '',
229:           target: c.target || c.to || '',
230:         })),
231:         variables: webhookVariables,
232:       };
233: 
234:       // Mark as running before execution starts
235:       await prisma.webhook_call_records.update({
236:         where: { id: callRecordId },
237:         data: { status: 'running' },
238:       });
239: 
240:       // Execute using V2 executor (agentic, same as manual Run and cron)
241:       const generator = workflowExecutorV2.execute(
242:         plan,
243:         config.organizationId,
244:         scopeId,
245:         'system',
246:       );
247: 
248:       // Drain the generator, collecting logs (same pattern as schedule runV2Execution)
249:       const logs: Array<{ type: string; content?: string; taskId?: string; taskTitle?: string; timestamp: string }> = [];
250:       let lastError: string | null = null;
251:       let logFlushCount = 0;
252: 
253:       for await (const event of generator) {
254:         const timestamp = new Date().toISOString();
255: 
256:         if (event.type === 'error') {
257:           lastError = event.message || 'Unknown error';
258:           logs.push({ type: 'error', content: lastError, timestamp });
259:         } else if (event.type === 'step_start') {
260:           logs.push({ type: 'step_start', taskId: event.taskId, taskTitle: event.taskTitle, timestamp });
261:         } else if (event.type === 'step_complete') {
262:           logs.push({ type: 'step_complete', taskId: event.taskId, taskTitle: event.taskTitle, timestamp });
263:         } else if (event.type === 'step_failed') {
264:           logs.push({ type: 'step_failed', taskId: event.taskId, taskTitle: event.taskTitle, content: event.message, timestamp });
265:         } else if (event.type === 'done') {
266:           logs.push({ type: 'done', timestamp });
267:         } else if (event.type === 'log') {
268:           const content = typeof event.content === 'string' ? event.content : JSON.stringify(event.content);
269:           logs.push({ type: 'log', content: content?.slice(0, 2000), timestamp });
270:         }
271: 
272:         // Persist logs periodically (every 5 events)
273:         if (++logFlushCount % 5 === 0) {
274:           prisma.webhook_call_records.update({
275:             where: { id: callRecordId },
276:             data: { logs: logs as any },
277:           }).catch(() => {});
278:         }
279:       }
280: 
281:       const responseTime = Date.now() - startTime;
282: 
283:       await prisma.webhook_call_records.update({
284:         where: { id: callRecordId },
285:         data: {
286:           status: lastError ? 'failed' : 'success',
287:           response_status: lastError ? 500 : 200,
288:           response_time_ms: responseTime,
289:           error_message: lastError,
290:           logs: logs as any,
291:         },
292:       });
293:     } catch (error: any) {
294:       const responseTime = Date.now() - startTime;
295: 
296:       await prisma.webhook_call_records.update({
297:         where: { id: callRecordId },
298:         data: {
299:           status: 'failed',
300:           response_status: 500,
301:           response_time_ms: responseTime,
302:           error_message: error.message,
303:         },
304:       });
305: 
306:       throw error;
307:     }
308:   }
