1: /**
2:  * OAuth Flow Service
3:  *
4:  * Handles OAuth 2.0 Authorization Code flow for data connectors.
5:  * Supports Google (Gmail, Maps, BigQuery) and Salesforce.
6:  *
7:  * Flow:
8:  *   1. Frontend calls GET /api/data-connectors/oauth/:provider/authorize
9:  *   2. Backend generates state, stores in Redis, returns authorize URL
10:  *   3. Frontend opens URL in popup
11:  *   4. User consents on provider's page
12:  *   5. Provider redirects to GET /api/data-connectors/oauth/:provider/callback
13:  *   6. Backend exchanges code for tokens, encrypts & stores, closes popup
14:  */
15: 
16: import crypto from 'crypto';
17: import { config } from '../config/index.js';
18: import { oauthProviderConfigService } from './oauth-provider-config.service.js';
19: import { AppError } from '../middleware/errorHandler.js';
20: 
21: // ---------------------------------------------------------------------------
22: // Provider configs
23: // ---------------------------------------------------------------------------
24: 
25: interface OAuthProviderConfig {
26:   authorizeUrl: string;
27:   tokenUrl: string;
28:   clientId: string;
29:   clientSecret: string;
30:   scopes: string[];
31:   extraParams?: Record<string, string>;
32: }
33: 
34: async function getProviderConfig(provider: string, orgId: string): Promise<OAuthProviderConfig> {
35:   // Read client credentials from database (configured by admin via UI)
36:   const dbConfig = await oauthProviderConfigService.getWithSecret(orgId, provider);
37: 
38:   // Fallback to env vars for backward compatibility
39:   const clientId = dbConfig?.clientId
40:     ?? (provider === 'google' ? config.connectorOAuth.google.clientId : '')
41:     ?? (provider === 'salesforce' ? config.connectorOAuth.salesforce.clientId : '');
42:   const clientSecret = dbConfig?.clientSecret
43:     ?? (provider === 'google' ? config.connectorOAuth.google.clientSecret : '')
44:     ?? (provider === 'salesforce' ? config.connectorOAuth.salesforce.clientSecret : '');
45: 
46:   if (!clientId || !clientSecret) {
47:     throw AppError.validation(
48:       `OAuth not configured for ${provider}. Please configure Client ID and Client Secret in the connector settings.`
49:     );
50:   }
51: 
52:   switch (provider) {
53:     case 'google':
54:       return {
55:         authorizeUrl: 'https://accounts.google.com/o/oauth2/v2/auth',
56:         tokenUrl: 'https://oauth2.googleapis.com/token',
57:         clientId, clientSecret,
58:         scopes: dbConfig?.scopes ?? [
59:           'https://www.googleapis.com/auth/gmail.readonly',
60:           'https://www.googleapis.com/auth/gmail.send',
61:           'https://www.googleapis.com/auth/gmail.modify',
62:         ],
63:         extraParams: { access_type: 'offline', prompt: 'consent' },
64:       };
65:     case 'salesforce':
66:       return {
67:         authorizeUrl: 'https://login.salesforce.com/services/oauth2/authorize',
68:         tokenUrl: 'https://login.salesforce.com/services/oauth2/token',
69:         clientId, clientSecret,
70:         scopes: dbConfig?.scopes ?? ['api', 'refresh_token'],
71:         extraParams: {},
72:       };
73:     default:
74:       throw AppError.validation(`Unsupported OAuth provider: ${provider}`);
75:   }
76: }
77: 
78: // ---------------------------------------------------------------------------
79: // In-memory state store (use Redis in production)
80: // ---------------------------------------------------------------------------
81: 
82: const pendingStates = new Map<string, { provider: string; orgId: string; userId: string; createdAt: number }>();
83: 
84: // Clean up expired states every 5 minutes
85: setInterval(() => {
86:   const now = Date.now();
87:   for (const [key, val] of pendingStates) {
88:     if (now - val.createdAt > 10 * 60 * 1000) pendingStates.delete(key);
89:   }
90: }, 5 * 60 * 1000);
91: 
92: // ---------------------------------------------------------------------------
93: // Service
94: // ---------------------------------------------------------------------------
95: 
96: export class OAuthFlowService {
97: 
98:   /**
99:    * Generate the authorization URL for the popup.
100:    * Returns the URL that the frontend should open in a popup window.
101:    */
102:   async getAuthorizeUrl(provider: string, orgId: string, userId: string): Promise<string> {
103:     const providerConfig = await getProviderConfig(provider, orgId);
104: 
105:     // Generate CSRF state token
106:     const state = crypto.randomBytes(32).toString('hex');
107:     pendingStates.set(state, { provider, orgId, userId, createdAt: Date.now() });
108: 
109:     const redirectUri = `${config.connectorOAuth.redirectBaseUrl}/api/data-connectors/oauth/${provider}/callback`;
110: 
111:     const params = new URLSearchParams({
112:       client_id: providerConfig.clientId,
113:       redirect_uri: redirectUri,
114:       response_type: 'code',
115:       scope: providerConfig.scopes.join(' '),
116:       state,
117:       ...providerConfig.extraParams,
118:     });
119: 
120:     return `${providerConfig.authorizeUrl}?${params.toString()}`;
121:   }
122: 
123:   /**
124:    * Handle the OAuth callback — exchange code for tokens.
125:    * Returns the tokens (caller is responsible for encrypting & storing).
126:    */
127:   async handleCallback(
128:     provider: string,
129:     code: string,
130:     state: string,
131:   ): Promise<{
132:     orgId: string;
133:     userId: string;
134:     accessToken: string;
135:     refreshToken: string | null;
136:     expiresIn: number;
137:     scope: string;
138:     tokenType: string;
139:     raw: Record<string, unknown>;
140:   }> {
141:     // Validate state
142:     const pending = pendingStates.get(state);
143:     if (!pending) throw AppError.validation('Invalid or expired OAuth state');
144:     if (pending.provider !== provider) throw AppError.validation('OAuth provider mismatch');
145:     pendingStates.delete(state);
146: 
147:     // Check expiry (10 min)
148:     if (Date.now() - pending.createdAt > 10 * 60 * 1000) {
149:       throw AppError.validation('OAuth state expired');
150:     }
151: 
152:     const providerConfig = await getProviderConfig(provider, pending.orgId);
153:     const redirectUri = `${config.connectorOAuth.redirectBaseUrl}/api/data-connectors/oauth/${provider}/callback`;
154: 
155:     // Exchange code for tokens
156:     const tokenRes = await fetch(providerConfig.tokenUrl, {
157:       method: 'POST',
158:       headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
159:       body: new URLSearchParams({
160:         client_id: providerConfig.clientId,
161:         client_secret: providerConfig.clientSecret,
162:         code,
163:         grant_type: 'authorization_code',
164:         redirect_uri: redirectUri,
165:       }),
166:     });
167: 
168:     if (!tokenRes.ok) {
169:       const errBody = await tokenRes.text();
170:       console.error(`[oauth] Token exchange failed for ${provider}:`, errBody);
171:       throw AppError.validation(`OAuth token exchange failed: ${tokenRes.status}`);
172:     }
173: 
174:     const tokens = await tokenRes.json() as Record<string, unknown>;
175: 
176:     return {
177:       orgId: pending.orgId,
178:       userId: pending.userId,
179:       accessToken: tokens.access_token as string,
180:       refreshToken: (tokens.refresh_token as string) ?? null,
181:       expiresIn: (tokens.expires_in as number) ?? 3600,
182:       scope: (tokens.scope as string) ?? '',
183:       tokenType: (tokens.token_type as string) ?? 'Bearer',
184:       raw: tokens,
185:     };
186:   }
187: 
188:   /**
189:    * Refresh an OAuth access token using a refresh token.
190:    */
191:   async refreshToken(
192:     provider: string,
193:     refreshToken: string,
194:     orgId: string,
195:   ): Promise<{ accessToken: string; refreshToken: string | null; expiresIn: number }> {
196:     const providerConfig = await getProviderConfig(provider, orgId);
197: 
198:     const res = await fetch(providerConfig.tokenUrl, {
199:       method: 'POST',
200:       headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
201:       body: new URLSearchParams({
202:         client_id: providerConfig.clientId,
203:         client_secret: providerConfig.clientSecret,
204:         refresh_token: refreshToken,
205:         grant_type: 'refresh_token',
206:       }),
207:     });
208: 
209:     if (!res.ok) {
210:       throw AppError.validation(`OAuth token refresh failed: ${res.status}`);
211:     }
212: 
213:     const data = await res.json() as Record<string, unknown>;
214: 
215:     return {
216:       accessToken: data.access_token as string,
217:       refreshToken: (data.refresh_token as string) ?? null,
218:       expiresIn: (data.expires_in as number) ?? 3600,
219:     };
220:   }
221: }
222: 
223: export const oauthFlowService = new OAuthFlowService();

