39:   return async (input: any, _toolUseId: string | undefined) => {
40:     const filePath: string | undefined = input?.tool_input?.file_path
41:       ?? input?.tool_input?.path;
42: 
43:     if (!filePath || !filePath.startsWith('/workspace/')) return {};
44: 
45:     const relativePath = filePath.replace('/workspace/', '');
46: 
47:     // Skip auto-generated directories that should never be synced to S3
48:     const firstSegment = relativePath.split('/')[0];
49:     const SKIP_PREFIXES = new Set([
50:       'node_modules', '.git', '__pycache__', '.venv', 'venv',
51:       '.next', '.nuxt', '.turbo', '.cache', '.parcel-cache',
52:       'bower_components', '.gradle', 'target', '.cargo',
53:     ]);
54:     if (SKIP_PREFIXES.has(firstSegment)) return {};
55: 
56:     const key = `${prefix}${relativePath}`;
57: 
58:     try {
59:       if (!fs.existsSync(filePath)) return {}; // file was deleted by the tool
60:       const content = fs.readFileSync(filePath);
61:       await s3.send(new PutObjectCommand({
62:         Bucket: bucket,
63:         Key: key,
64:         Body: content,
65:         ContentLength: content.length,
66:       }));
67:       console.log(`[hook:PostToolUse] Synced ${relativePath} → s3://${bucket}/${key}`);
68:     } catch (err) {
69:       console.warn(`[hook:PostToolUse] Failed to sync ${relativePath}:`, err);
70:     }
71: 
72:     return {};
73:   };
74: }
