116: /**
117:  * Create a git baseline snapshot of the current workspace state.
118:  * Called BEFORE the agent runs so we can diff against it later.
119:  */
120: export function createGitBaseline(): boolean {
121:   try {
122:     // Check if git is available
123:     execSync('which git', { stdio: 'ignore' });
124:   } catch {
125:     console.warn('[git-diff] git not available in container, skipping baseline');
126:     return false;
127:   }
128: 
129:   try {
130:     // Configure git (required for commit)
131:     execSync('git config user.email "agent@superagent.local"', { cwd: WORKSPACE_DIR, stdio: 'ignore' });
132:     execSync('git config user.name "Agent"', { cwd: WORKSPACE_DIR, stdio: 'ignore' });
133: 
134:     // Init repo if not already (idempotent)
135:     execSync('git init', { cwd: WORKSPACE_DIR, stdio: 'ignore' });
136: 
137:     // Stage everything and commit as baseline
138:     execSync('git add -A', { cwd: WORKSPACE_DIR, stdio: 'ignore' });
139: 
140:     // Check if there's anything to commit
141:     try {
142:       execSync('git diff --cached --quiet', { cwd: WORKSPACE_DIR, stdio: 'ignore' });
143:       // No changes staged — either empty workspace or already committed
144:       // Try committing anyway (might be initial commit)
145:       try {
146:         execSync('git commit -m "baseline" --allow-empty', { cwd: WORKSPACE_DIR, stdio: 'ignore' });
147:       } catch { /* already committed, fine */ }
148:     } catch {
149:       // There are staged changes, commit them
150:       execSync('git commit -m "baseline"', { cwd: WORKSPACE_DIR, stdio: 'ignore' });
151:     }
152: 
153:     console.log('[git-diff] Baseline snapshot created');
154:     return true;
155:   } catch (err) {
156:     console.warn('[git-diff] Failed to create baseline:', err instanceof Error ? err.message : err);
157:     return false;
158:   }
159: }
