161: /**
162:  * Extract diff between baseline and current state, upload as __diff__.json to S3.
163:  */
164: function extractAndUploadDiff(bucket: string, prefix: string): void {
165:   // Check if git repo exists
166:   if (!fs.existsSync(`${WORKSPACE_DIR}/.git`)) {
167:     console.log('[git-diff] No git repo found, skipping diff extraction');
168:     return;
169:   }
170: 
171:   try {
172:     // Stage all current changes
173:     execSync('git add -A', { cwd: WORKSPACE_DIR, stdio: 'ignore' });
174: 
175:     // Get diff stat (structured)
176:     let diffStatOutput = '';
177:     try {
178:       diffStatOutput = execSync('git diff --cached --numstat HEAD', {
179:         cwd: WORKSPACE_DIR,
180:         encoding: 'utf-8',
181:         maxBuffer: 10 * 1024 * 1024,
182:       }).trim();
183:     } catch { /* no changes */ }
184: 
185:     if (!diffStatOutput) {
186:       console.log('[git-diff] No changes detected');
187:       return;
188:     }
189: 
190:     // Parse numstat: "insertions\tdeletions\tfilepath"
191:     const files: Array<{ path: string; status: string; insertions: number; deletions: number }> = [];
192:     for (const line of diffStatOutput.split('\n')) {
193:       if (!line.trim()) continue;
194:       const [ins, del, filePath] = line.split('\t');
195:       // Binary files show as "-\t-\tfilepath"
196:       const insertions = ins === '-' ? 0 : parseInt(ins, 10) || 0;
197:       const deletions = del === '-' ? 0 : parseInt(del, 10) || 0;
198:       files.push({ path: filePath, status: 'modified', insertions, deletions });
199:     }
200: 
201:     // Get name-status to determine add/modify/delete
202:     let nameStatusOutput = '';
203:     try {
204:       nameStatusOutput = execSync('git diff --cached --name-status HEAD', {
205:         cwd: WORKSPACE_DIR,
206:         encoding: 'utf-8',
207:         maxBuffer: 10 * 1024 * 1024,
208:       }).trim();
209:     } catch { /* ignore */ }
210: 
211:     const statusMap = new Map<string, string>();
212:     for (const line of nameStatusOutput.split('\n')) {
213:       if (!line.trim()) continue;
214:       const [status, ...pathParts] = line.split('\t');
215:       const filePath = pathParts.join('\t'); // handle paths with tabs (unlikely but safe)
216:       const statusLabel = status.startsWith('A') ? 'added'
217:         : status.startsWith('D') ? 'deleted'
218:         : status.startsWith('R') ? 'renamed'
219:         : 'modified';
220:       statusMap.set(filePath, statusLabel);
221:     }
222: 
223:     // Merge status into files
224:     for (const f of files) {
225:       f.status = statusMap.get(f.path) ?? f.status;
226:     }
227: 
228:     const totalInsertions = files.reduce((sum, f) => sum + f.insertions, 0);
229:     const totalDeletions = files.reduce((sum, f) => sum + f.deletions, 0);
230: 
231:     const diffStat = {
232:       files_changed: files.length,
233:       insertions: totalInsertions,
234:       deletions: totalDeletions,
235:       files,
236:     };
237: 
238:     // Get full unified diff (capped at 1MB to avoid huge diffs)
239:     let diffPatch = '';
240:     try {
241:       diffPatch = execSync('git diff --cached HEAD', {
242:         cwd: WORKSPACE_DIR,
243:         encoding: 'utf-8',
244:         maxBuffer: 10 * 1024 * 1024,
245:       });
246:     } catch { /* ignore if too large */ }
247: 
248:     // Cap patch size at 1MB
249:     if (diffPatch.length > 1024 * 1024) {
250:       diffPatch = diffPatch.substring(0, 1024 * 1024) + '\n\n... (diff truncated, exceeded 1MB)';
251:     }
252: 
253:     const diffData = {
254:       diff_stat: diffStat,
255:       diff_patch: diffPatch,
256:       created_at: new Date().toISOString(),
257:     };
258: 
259:     // Upload to S3 as __diff__.json
260:     const key = `${prefix}__diff__.json`;
261:     s3.send(new PutObjectCommand({
262:       Bucket: bucket,
263:       Key: key,
264:       Body: JSON.stringify(diffData),
265:       ContentType: 'application/json',
266:     })).then(() => {
267:       console.log(`[git-diff] Uploaded diff (${files.length} files, +${totalInsertions}/-${totalDeletions}) → s3://${bucket}/${key}`);
268:     }).catch(err => {
269:       console.warn('[git-diff] Failed to upload diff to S3:', err);
270:     });
271: 
272:   } catch (err) {
273:     console.warn('[git-diff] Diff extraction failed:', err instanceof Error ? err.message : err);
274:   }
275: }
