281: export async function* runAgent(payload: AgentPayload): AsyncGenerator<AgentEvent> {
282:   const baseOptions: Record<string, unknown> = {
283:     systemPrompt: payload.system_prompt ?? undefined,
284:     allowedTools: payload.allowed_tools ?? DEFAULT_TOOLS,
285:     cwd: '/workspace',
286:     permissionMode: 'bypassPermissions',
287:     allowDangerouslySkipPermissions: true,
288:     settingSources: ['project'],
289:   };
290: 
291:   // Dynamic model override: pass directly to SDK options so it takes effect
292:   // per-invocation (env var approach only works for the first call in a session).
293:   if (payload.model) {
294:     baseOptions.model = payload.model;
295:     console.log(`[agent-runner] Model override via options: ${payload.model}`);
296:   }
297: 
298:   if (payload.mcp_servers && Object.keys(payload.mcp_servers).length > 0) {
299:     baseOptions.mcpServers = payload.mcp_servers;
300:   }
301: 
302:   // Register S3 sync hooks (replaces file-watcher)
303:   const bucket = payload.workspace_s3_bucket;
304:   const prefix = payload.workspace_s3_prefix;
305:   if (bucket && prefix) {
306:     baseOptions.hooks = {
307:       PostToolUse: [
308:         {
309:           matcher: 'Write|Edit',
310:           hooks: [createFileChangeHook(bucket, prefix)],
311:         },
312:       ],
313:       Stop: [
314:         {
315:           hooks: [createStopHook(bucket, prefix)],
316:         },
317:       ],
318:     };
319:     console.log(`[agent-runner] S3 sync hooks registered for s3://${bucket}/${prefix}`);
320:   }
321: 
322:   // Strategy: try Claude Code session resume first (fast, native history).
323:   // If resume fails (microVM was recycled), fallback to history-injected prompt.
324:   if (payload.session_id) {
325:     try {
326:       yield* runWithOptions(payload.prompt, { ...baseOptions, resume: payload.session_id });
327:       return;
328:     } catch (err) {
329:       console.log(`[agent-runner] Session resume failed (${err}), falling back to history injection`);
330:     }
331:   }
332: 
333:   const prompt = buildContextualPrompt(payload);
334:   yield* runWithOptions(prompt, baseOptions);
335: }
