341: async function* runWithOptions(
342:   prompt: string,
343:   options: Record<string, unknown>,
344: ): AsyncGenerator<AgentEvent> {
345:   const seenBrowserSessions = new Set<string>();
346:   const browserSessionCounts = new Map<string, number>();
347: 
348:   for await (const message of query({ prompt, options })) {
349:     const msg = message as Record<string, unknown>;
350: 
351:     if (msg.type === 'system' && msg.subtype === 'init') {
352:       yield {
353:         type: 'session_start',
354:         session_id: msg.session_id as string,
355:       };
356:       continue;
357:     }
358: 
359:     if (msg.type === 'assistant') {
360:       const rawContent = (msg.message as Record<string, unknown>)?.content;
361:       const model = (msg.message as Record<string, unknown>)?.model as string | undefined;
362:       const blocks = Array.isArray(rawContent)
363:         ? rawContent.map(mapContentBlock)
364:         : [];
365:       
366:       yield {
367:         type: 'assistant',
368:         content: blocks,
369:         session_id: msg.session_id as string | undefined,
370:         model,
371:       };
372: 
373:       // Check for browser tool_use blocks and extract live view URL
374:       const liveViewEvent = await extractLiveViewFromAssistant(
375:         blocks, seenBrowserSessions, browserSessionCounts
376:       );
377:       if (liveViewEvent) {
378:         yield liveViewEvent;
379:       }
380: 
381:       continue;
382:     }
383: 
384:     if (msg.type === 'result') {
385:       const resultMsg = msg as Record<string, unknown>;
386:       // Extract token usage from SDK result message
387:       const usage = resultMsg.usage as Record<string, number> | undefined;
388:       const modelUsage = resultMsg.modelUsage as Record<string, Record<string, number>> | undefined;
389:       let tokenUsage: import('./types.js').TokenUsage | undefined;
390: 
391:       if (usage) {
392:         tokenUsage = {
393:           input_tokens: usage.input_tokens ?? 0,
394:           output_tokens: usage.output_tokens ?? 0,
395:           cache_read_input_tokens: usage.cache_read_input_tokens ?? 0,
396:           cache_creation_input_tokens: usage.cache_creation_input_tokens ?? 0,
397:           total_cost_usd: (resultMsg.total_cost_usd as number) ?? 0,
398:         };
399:       } else if (modelUsage) {
400:         // Aggregate from per-model usage
401:         let inputTokens = 0, outputTokens = 0, cacheRead = 0, cacheCreation = 0, cost = 0;
402:         for (const mu of Object.values(modelUsage)) {
403:           inputTokens += mu.inputTokens ?? 0;
404:           outputTokens += mu.outputTokens ?? 0;
405:           cacheRead += mu.cacheReadInputTokens ?? 0;
406:           cacheCreation += mu.cacheCreationInputTokens ?? 0;
407:           cost += mu.costUSD ?? 0;
408:         }
409:         tokenUsage = {
410:           input_tokens: inputTokens,
411:           output_tokens: outputTokens,
412:           cache_read_input_tokens: cacheRead,
413:           cache_creation_input_tokens: cacheCreation,
414:           total_cost_usd: cost,
415:         };
416:       }
417: 
418:       yield {
419:         type: 'result',
420:         session_id: msg.session_id as string | undefined,
421:         duration_ms: msg.duration_ms as number | undefined,
422:         num_turns: msg.num_turns as number | undefined,
423:         is_error: msg.is_error as boolean | undefined,
424:         result: msg.result as string | undefined,
425:         token_usage: tokenUsage,
426:       };
427:       continue;
428:     }
429:   }
430: }
