432: function buildContextualPrompt(payload: AgentPayload): string {
433:   const userMessage = payload.prompt;
434:   const history = payload.history;
435: 
436:   if (!history || history.length === 0) {
437:     return userMessage;
438:   }
439: 
440:   const contextParts = history.map(msg =>
441:     msg.role === 'user' ? `User: ${msg.content}` : `Assistant: ${msg.content}`,
442:   );
443: 
444:   return (
445:     `Here is our conversation so far:\n\n${contextParts.join('\n\n')}\n\n` +
446:     `Now the user says:\n${userMessage}\n\n` +
447:     `Please respond based on the full conversation context above.`
448:   );
449: }
