451: /**
452:  * Check assistant content blocks for browser tool_use with session_id.
453:  * When detected (on the 2nd occurrence to ensure session is ready),
454:  * call GetBrowserSession from inside the container to get the live view URL.
455:  */
456: /**
457:  * Check assistant content blocks for live_view_url from start_browser_session result.
458:  * The MCP server returns live_view_url directly in the tool response.
459:  * We look for it in tool_result blocks or text blocks containing the URL.
460:  */
461: async function extractLiveViewFromAssistant(
462:   blocks: ContentBlock[],
463:   seenSessions: Set<string>,
464:   sessionCounts: Map<string, number>,
465: ): Promise<AgentEvent | null> {
466:   for (const block of blocks) {
467:     // Check any block that might contain live_view_url
468:     const content = block.content ?? block.text ?? '';
469:     const contentStr = typeof content === 'string' ? content : JSON.stringify(content);
470:     
471:     if (contentStr.includes('live_view_url')) {
472:       try {
473:         // Try to extract JSON containing live_view_url
474:         const jsonMatch = contentStr.match(/\{[^{}]*"live_view_url"\s*:\s*"[^"]+?"[^{}]*\}/);
475:         if (jsonMatch) {
476:           const parsed = JSON.parse(jsonMatch[0]);
477:           if (parsed.live_view_url && parsed.session_id) {
478:             if (seenSessions.has(parsed.session_id)) continue;
479:             seenSessions.add(parsed.session_id);
480:             return {
481:               type: 'browser_live_view_ready',
482:               sessionId: parsed.session_id,
483:               liveViewUrl: parsed.live_view_url,
484:               browserIdentifier: parsed.browser_identifier ?? 'aws.browser.v1',
485:             } as AgentEvent;
486:           }
487:         }
488:         // Try parsing the whole content as JSON
489:         const fullParsed = JSON.parse(contentStr);
490:         if (fullParsed.live_view_url && fullParsed.session_id) {
491:           if (seenSessions.has(fullParsed.session_id)) continue;
492:           seenSessions.add(fullParsed.session_id);
493:           return {
494:             type: 'browser_live_view_ready',
495:             sessionId: fullParsed.session_id,
496:             liveViewUrl: fullParsed.live_view_url,
497:             browserIdentifier: fullParsed.browser_identifier ?? 'aws.browser.v1',
498:           } as AgentEvent;
499:         }
500:       } catch { /* not parseable, skip */ }
501:     }
502: 
503:     // Also extract live_view_url from raw text using regex
504:     if (contentStr.includes('bedrock-agentcore') && contentStr.includes('/live-view')) {
505:       const urlMatch = contentStr.match(/(https:\/\/bedrock-agentcore[^\s"',]+\/live-view)/);
506:       const sessionMatch = contentStr.match(/"?session_id"?\s*[:=]\s*"?([0-9A-Z]+)"?/i) 
507:         ?? contentStr.match(/sessions\/([0-9A-Z]+)\//i);
508:       if (urlMatch && sessionMatch) {
509:         const sessionId = sessionMatch[1];
510:         if (!seenSessions.has(sessionId)) {
511:           seenSessions.add(sessionId);
512:           return {
513:             type: 'browser_live_view_ready',
514:             sessionId,
515:             liveViewUrl: urlMatch[1],
516:             browserIdentifier: 'aws.browser.v1',
517:           } as AgentEvent;
518:         }
519:       }
520:     }
521: 
522:     // Track tool_use for session counting (debug)
523:     if (block.type === 'tool_use' && block.name) {
524:       const bare = block.name.includes('__') ? block.name.split('__').pop()! : block.name;
525:       if (bare.startsWith('browser_')) {
526:         const input = block.input as Record<string, unknown> | undefined;
527:         const sessionId = input?.session_id as string | undefined;
528:         if (sessionId) {
529:           const count = (sessionCounts.get(sessionId) ?? 0) + 1;
530:           sessionCounts.set(sessionId, count);
531:         }
532:       }
533:     }
534:   }
535:   return null;
536: }
