538: function mapContentBlock(block: Record<string, unknown>): ContentBlock {
539:   switch (block.type) {
540:     case 'text':
541:       return { type: 'text', text: block.text as string };
542:     case 'tool_use':
543:       return {
544:         type: 'tool_use',
545:         id: block.id as string,
546:         name: block.name as string,
547:         input: block.input,
548:       };
549:     case 'tool_result':
550:       return {
551:         type: 'tool_result',
552:         tool_use_id: block.tool_use_id as string,
553:         content: block.content as string | undefined,
554:         is_error: block.is_error as boolean | undefined,
555:       };
556:     default:
557:       return block as unknown as ContentBlock;
558:   }
559: }

