37: async function handleInvocations(
38:   req: http.IncomingMessage,
39:   res: http.ServerResponse,
40: ): Promise<void> {
41:   const chunks: Buffer[] = [];
42:   for await (const chunk of req) chunks.push(chunk as Buffer);
43: 
44:   let payload: AgentPayload;
45:   try {
46:     payload = JSON.parse(Buffer.concat(chunks).toString());
47:   } catch {
48:     res.writeHead(400, { 'Content-Type': 'application/json' });
49:     res.end(JSON.stringify({ error: 'Invalid JSON payload' }));
50:     return;
51:   }
52: 
53:   const bucket = payload.workspace_s3_bucket;
54:   const prefix = payload.workspace_s3_prefix;
55: 
56:   // --- Restore full workspace from S3 → /workspace/ ---
57:   if (bucket && prefix) {
58:     try {
59:       const count = await restoreWorkspaceFromS3(s3, bucket, prefix);
60:       console.log(`[index] Restored ${count} files from s3://${bucket}/${prefix}`);
61:     } catch (err) {
62:       console.error('[index] Workspace restore failed:', err);
63:     }
64: 
65:     // Create git baseline snapshot for diff tracking
66:     createGitBaseline();
67:   }
68: 
69:   // --- Set backend connectivity env vars for skills (e.g. knowledge-search) ---
70:   if (payload.backend_api_url) {
71:     process.env.API_BASE_URL = payload.backend_api_url;
72:   }
73:   if (payload.backend_api_key) {
74:     process.env.AUTH_TOKEN = payload.backend_api_key;
75:   }
