77:   // --- SSE streaming response ---
78:   // S3 sync is now handled by SDK hooks in agent-runner.ts:
79:   //   PostToolUse (Write|Edit) → incremental file sync
80:   //   Stop → full workspace sync (safety net)
81:   res.writeHead(200, {
82:     'Content-Type': 'text/event-stream',
83:     'Cache-Control': 'no-cache',
84:     'Connection': 'keep-alive',
85:   });
