87:   try {
88:     for await (const event of runAgent(payload)) {
89:       res.write(`data: ${JSON.stringify(event)}\n\n`);
90:     }
91:   } catch (err) {
92:     const errorEvent: AgentEvent = {
93:       type: 'error',
94:       code: 'AGENT_EXECUTION_ERROR',
95:       message: err instanceof Error ? err.message : String(err),
96:     };
97:     res.write(`data: ${JSON.stringify(errorEvent)}\n\n`);
98:   }
99: 
100:   res.end();
101: }
102: 
103: // ---------------------------------------------------------------------------
104: // /ping
105: // ---------------------------------------------------------------------------
106: 
107: function handlePing(res: http.ServerResponse): void {
108:   res.writeHead(200, { 'Content-Type': 'application/json' });
109:   res.end(JSON.stringify({
110:     status: 'Healthy',
111:     time_of_last_update: Math.floor(Date.now() / 1000),
112:   }));
113: }
114: 
115: // ---------------------------------------------------------------------------
116: // Server
117: // ---------------------------------------------------------------------------
118: 
119: const server = http.createServer(async (req, res) => {
120:   try {
121:     if (req.method === 'POST' && req.url === '/invocations') {
122:       await handleInvocations(req, res);
123:     } else if (req.method === 'GET' && req.url === '/ping') {
124:       handlePing(res);
125:     } else {
126:       res.writeHead(404, { 'Content-Type': 'application/json' });
127:       res.end(JSON.stringify({ error: 'Not found' }));
128:     }
129:   } catch (err) {
130:     console.error('[index] Unhandled error:', err);
131:     if (!res.headersSent) {
132:       res.writeHead(500, { 'Content-Type': 'application/json' });
133:       res.end(JSON.stringify({ error: 'Internal server error' }));
134:     }
135:   }
136: });
137: 
138: server.listen(PORT, '0.0.0.0', () => {
139:   console.log(`[agentcore-runner] Listening on 0.0.0.0:${PORT}`);
140: });
